package com.slayertaskloot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntFunction;
import org.junit.Test;

public class TaskNettingTest
{
	private static final int SHARK = 385;
	private static final int PRAYER_POTION_4 = 2434;
	private static final int PRAYER_POTION_3 = 139;
	private static final int PRAYER_POTION_2 = 141;
	private static final int PRAYER_POTION_1 = 143;
	private static final int SUPER_RESTORE_4 = 3024;

	private static final IntFunction<String> NAMES;

	static
	{
		final Map<Integer, String> names = new HashMap<>();
		names.put(SHARK, "Shark");
		names.put(PRAYER_POTION_4, "Prayer potion(4)");
		names.put(PRAYER_POTION_3, "Prayer potion(3)");
		names.put(PRAYER_POTION_2, "Prayer potion(2)");
		names.put(PRAYER_POTION_1, "Prayer potion(1)");
		names.put(SUPER_RESTORE_4, "Super restore(4)");
		NAMES = id -> names.getOrDefault(id, "Item #" + id);
	}

	@Test
	public void taskFoodUsedNetsOutOfLootFirst()
	{
		final TaskNetting.Result result = TaskNetting.apply(
			Map.of(SHARK, 5), Map.of(SHARK, 500L),
			Map.of(SHARK, new SupplyEntry(2, 200L, false)), NAMES);

		assertEquals(Integer.valueOf(3), result.getLootQuantities().get(SHARK));
		assertEquals(Long.valueOf(300L), result.getLootValues().get(SHARK));
		assertFalse(result.getSupplies().containsKey(SHARK));
	}

	@Test
	public void excessUsageRemainsAsSupply()
	{
		final TaskNetting.Result result = TaskNetting.apply(
			Map.of(SHARK, 2), Map.of(SHARK, 200L),
			Map.of(SHARK, new SupplyEntry(5, 500L, false)), NAMES);

		assertFalse(result.getLootQuantities().containsKey(SHARK));
		assertEquals(3, result.getSupplies().get(SHARK).getQuantity());
		assertEquals(300L, result.getSupplies().get(SHARK).getValue());
	}

	@Test
	public void aFullyDrunkDroppedPotionCancelsBothWays()
	{
		// The reported bug: food netted and potions didn't, so a dropped potion drunk dry stayed
		// in Drops at full value while its doses stayed in Supplies.
		final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
		supplies.put(PRAYER_POTION_4, new SupplyEntry(4, 400L, true));
		final TaskNetting.Result result = TaskNetting.apply(
			Map.of(PRAYER_POTION_4, 1), Map.of(PRAYER_POTION_4, 400L), supplies, NAMES);

		assertFalse(result.getLootQuantities().containsKey(PRAYER_POTION_4));
		assertFalse(result.getSupplies().containsKey(PRAYER_POTION_4));
	}

	@Test
	public void dosesCancelAcrossTheVariantThatDropped()
	{
		// Charged under the 4-dose container, dropped as a 3-dose. Only the name connects them.
		final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
		supplies.put(PRAYER_POTION_4, new SupplyEntry(3, 300L, true));
		final TaskNetting.Result result = TaskNetting.apply(
			Map.of(PRAYER_POTION_3, 1), Map.of(PRAYER_POTION_3, 300L), supplies, NAMES);

		assertFalse(result.getLootQuantities().containsKey(PRAYER_POTION_3));
		assertFalse(result.getSupplies().containsKey(PRAYER_POTION_4));
	}

	@Test
	public void aPartlyDrunkDropBecomesTheContainerStillHeld()
	{
		// A 3-dose drops and two doses are drunk. What the player is holding is a 1-dose, and that
		// is what Drops now says. Cancelling only whole containers left this showing a full 3-dose
		// against a 2-dose charge — right arithmetic, and the same "both rows still there" reading
		// the original bug was reported as.
		final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
		supplies.put(PRAYER_POTION_4, new SupplyEntry(2, 200L, true));
		final TaskNetting.Result result = TaskNetting.apply(
			Map.of(PRAYER_POTION_3, 1), Map.of(PRAYER_POTION_3, 300L), supplies, NAMES);

		assertFalse(result.getLootQuantities().containsKey(PRAYER_POTION_3));
		assertEquals(Integer.valueOf(1), result.getLootQuantities().get(PRAYER_POTION_1));
		assertEquals(Long.valueOf(100L), result.getLootValues().get(PRAYER_POTION_1));
		assertFalse(result.getSupplies().containsKey(PRAYER_POTION_4));
	}

	@Test
	public void aRemainderIsPackedIntoTheLargestContainersThatHoldIt()
	{
		// Eight doses dropped, three drunk. Five left reads as a 4-dose and a 1-dose rather than
		// five 1-doses — and neither denomination is one that dropped, which is the accepted cost.
		final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
		supplies.put(PRAYER_POTION_4, new SupplyEntry(3, 300L, true));
		final TaskNetting.Result result = TaskNetting.apply(
			Map.of(PRAYER_POTION_4, 2), Map.of(PRAYER_POTION_4, 800L), supplies, NAMES);

		assertEquals(Integer.valueOf(1), result.getLootQuantities().get(PRAYER_POTION_4));
		assertEquals(Integer.valueOf(1), result.getLootQuantities().get(PRAYER_POTION_1));
		assertFalse(result.getSupplies().containsKey(PRAYER_POTION_4));

		// Netting must take exactly as much out of Drops as it takes out of Supplies, so the
		// repackaging can never move the profit figure: 800 - 300 both before and after.
		assertEquals(500L, result.getLootValues().values().stream().mapToLong(Long::longValue).sum());
	}

	@Test
	public void dosesPoolAcrossEveryContainerThatDropped()
	{
		// Seven doses against a (4) and a (2): six cancel and the seventh stays charged, because
		// the drops only ever held six.
		final Map<Integer, Integer> loot = new LinkedHashMap<>();
		loot.put(PRAYER_POTION_4, 1);
		loot.put(PRAYER_POTION_2, 1);
		final Map<Integer, Long> values = new LinkedHashMap<>();
		values.put(PRAYER_POTION_4, 400L);
		values.put(PRAYER_POTION_2, 200L);
		final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
		supplies.put(PRAYER_POTION_4, new SupplyEntry(7, 700L, true));

		final TaskNetting.Result result = TaskNetting.apply(loot, values, supplies, NAMES);

		assertTrue(result.getLootQuantities().isEmpty());
		assertEquals(1, result.getSupplies().get(PRAYER_POTION_4).getQuantity());
		assertEquals(100L, result.getSupplies().get(PRAYER_POTION_4).getValue());
	}

	@Test
	public void dosesNeverCancelADifferentPotion()
	{
		final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
		supplies.put(SUPER_RESTORE_4, new SupplyEntry(4, 400L, true));
		final TaskNetting.Result result = TaskNetting.apply(
			Map.of(PRAYER_POTION_4, 1), Map.of(PRAYER_POTION_4, 400L), supplies, NAMES);

		assertEquals(Integer.valueOf(1), result.getLootQuantities().get(PRAYER_POTION_4));
		assertEquals(4, result.getSupplies().get(SUPER_RESTORE_4).getQuantity());
	}

	@Test
	public void aChargedItemNeverCancelsAgainstADropOfItself()
	{
		final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
		supplies.put(SHARK, new SupplyEntry(3, 300L, false, Map.of(SHARK, 100)));
		final TaskNetting.Result result = TaskNetting.apply(
			Map.of(SHARK, 5), Map.of(SHARK, 500L), supplies, NAMES);

		assertEquals(Integer.valueOf(5), result.getLootQuantities().get(SHARK));
		assertEquals(3, result.getSupplies().get(SHARK).getQuantity());
	}
}

package com.slayertaskloot;

import static org.junit.Assert.assertEquals;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.game.ItemStack;
import org.junit.Test;

public class LootBufferTest
{
	@Test
	public void bufferedLootDoesNotShareRuneliteBackingList()
	{
		final List<ItemStack> eventItems = new ArrayList<>();
		eventItems.add(new ItemStack(995, 100));

		final List<ItemStack> buffered = SlayerTaskLootPlugin.copyLoot(eventItems);
		eventItems.clear();

		assertEquals(1, buffered.size());
		assertEquals(995, buffered.get(0).getId());
		assertEquals(100, buffered.get(0).getQuantity());
	}

	/**
	 * A fight longer than the configured window still counts as one fight, so an Araxxor kill
	 * doesn't lose the supplies that paid for it while a regular araxyte keeps them.
	 */
	@Test
	public void graceWindowStretchesToCoverTheCurrentFight()
	{
		// 50-tick window, fight started 120 ticks ago: the fight wins.
		assertEquals(80, SlayerTaskLootPlugin.graceCutoff(200, 50, 80, 500));

		// Short fight inside the window: the window wins, never shortened by combat.
		assertEquals(150, SlayerTaskLootPlugin.graceCutoff(200, 50, 190, 500));

		// Not in combat at all.
		assertEquals(150, SlayerTaskLootPlugin.graceCutoff(200, 50, -1, 500));

		// An unbroken streak can't reach back past the ceiling.
		assertEquals(500, SlayerTaskLootPlugin.graceCutoff(1000, 50, 20, 500));

		// A window of zero means what it says.
		assertEquals(200, SlayerTaskLootPlugin.graceCutoff(200, 0, 20, 500));

		// The anchor is back-dated to before the attack that produced the first hitsplat, so a
		// charge on the throwing tick still falls inside it rather than one tick outside.
		assertEquals(78, SlayerTaskLootPlugin.graceCutoff(200, 50, 78, 500));
	}

	@Test
	public void resolvesLoadedBlowpipeDartNames()
	{
		assertEquals(806, SlayerTaskLootPlugin.dartId("Bronze dart"));
		assertEquals(25849, SlayerTaskLootPlugin.dartId("Amethyst dart"));
		assertEquals(11230, SlayerTaskLootPlugin.dartId("Dragon dart"));
		assertEquals(-1, SlayerTaskLootPlugin.dartId("Unknown dart"));
	}

	@Test
	public void groundPickupAndInventoryGainAreOnlyCountedOnce()
	{
		final Map<Integer, Integer> ignores = new HashMap<>();
		ignores.put(200, 3);

		assertEquals(0, SlayerTaskLootPlugin.applyPickupInventoryIgnore(ignores, 200, 3));
		assertEquals(0, ignores.size());
	}

	@Test
	public void directToContainerPickupKeepsItsDespawnSignal()
	{
		final Map<Integer, Integer> ignores = new HashMap<>();
		ignores.put(200, 3);

		// No INV gain is presented, so the separately queued despawn quantity remains intact.
		assertEquals(0, SlayerTaskLootPlugin.applyPickupInventoryIgnore(ignores, 200, 0));
		assertEquals(Integer.valueOf(3), ignores.get(200));
	}

	@Test
	public void pickupSuppressionOnlyAbsorbsItsOwnQuantity()
	{
		final Map<Integer, Integer> ignores = new HashMap<>();
		ignores.put(200, 2);

		assertEquals(3, SlayerTaskLootPlugin.applyPickupInventoryIgnore(ignores, 200, 5));
		assertEquals(0, ignores.size());
	}

	@Test
	public void recognisesPortableStorageActions()
	{
		assertEquals(true, SlayerTaskLootPlugin.isRemoteStorageAction("Fill"));
		assertEquals(true, SlayerTaskLootPlugin.isRemoteStorageAction("Bank-All"));
		assertEquals(true, SlayerTaskLootPlugin.isRemoteStorageAction("Deposit"));
		assertEquals(false, SlayerTaskLootPlugin.isRemoteStorageAction("Drink"));
	}

	@Test
	public void groundStackReductionConfirmsAutomaticContainerPickup()
	{
		assertEquals(1, SlayerTaskLootPlugin.removedGroundQuantity(1, 0));
		assertEquals(25, SlayerTaskLootPlugin.removedGroundQuantity(100, 75));
		assertEquals(0, SlayerTaskLootPlugin.removedGroundQuantity(100, 100));
		assertEquals(0, SlayerTaskLootPlugin.removedGroundQuantity(100, -1));
	}

	@Test
	public void recognisesAlchemySpellTargets()
	{
		assertEquals(true, SlayerTaskLootPlugin.isAlchemyCast(
			"Cast", "High Level Alchemy -> Rune platebody"));
		assertEquals(true, SlayerTaskLootPlugin.isAlchemyCast(
			"cast", "Low Level Alchemy -> Yew longbow"));
		assertEquals(false, SlayerTaskLootPlugin.isAlchemyCast("Use", "High Level Alchemy"));
		assertEquals(false, SlayerTaskLootPlugin.isAlchemyCast("Cast", "Fire Blast"));
	}
}

package com.slayertaskloot;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class SlayerTaskTargetsTest
{
	@Test
	public void matchesOrdinarySuperiorAndBossTargets()
	{
		assertTrue(SlayerTaskTargets.matches("Smoke devils", "Smoke devil"));
		assertTrue(SlayerTaskTargets.matches("Dust devils", "Choke devil"));
		assertTrue(SlayerTaskTargets.matches("Blue dragons", "Vorkath"));
		assertTrue(SlayerTaskTargets.matches("Araxytes", "Araxxor"));
		// Shares no word with its assignment, so only the alias can connect the two.
		assertTrue(SlayerTaskTargets.matches("Rats", "Scurrius"));
		assertTrue(SlayerTaskTargets.matches("Rats", "Giant rat"));
		// An alias that carries a hyphen of its own has to be folded the same way the NPC name is,
		// or it stops matching the moment the hyphen becomes a word break on one side only.
		assertTrue(SlayerTaskTargets.matches("Fossil island wyverns", "Long-tailed wyvern"));
	}

	/**
	 * Araxxor's hatched minions award slayer experience and count towards the helmet, but killing
	 * one never moves the assignment counter and never drops anything. Counting them booked three
	 * or four kills for every Araxxor actually killed — a dozen kills read as 38.
	 */
	@Test
	public void doesNotCountAraxxorMinionsAsKills()
	{
		for (String minion : new String[]{"Mirrorback Araxyte", "Ruptura Araxyte", "Acidic Araxyte"})
		{
			// Still part of the fight, so supplies spent on them still belong to the task.
			assertTrue(minion, SlayerTaskTargets.matches("Araxytes", minion));
			assertFalse(minion, SlayerTaskTargets.countsTowardTask("Araxytes", minion));
			assertFalse(minion, SlayerTaskTargets.countsTowardTask("Spiders", minion));
		}

		// Everything the assignment does count still counts, the superior included.
		assertTrue(SlayerTaskTargets.countsTowardTask("Araxytes", "Araxyte"));
		assertTrue(SlayerTaskTargets.countsTowardTask("Araxytes", "Araxxor"));
		assertTrue(SlayerTaskTargets.countsTowardTask("Araxytes", "Dreadborn Araxyte"));
	}

	/**
	 * A boss whose name ends in an s is not a plural. Singularising first left "sarachni", which
	 * matched the NPC nowhere, so the assignment recognised none of its own kills: the counter
	 * still banked them, but no session opened and neither loot nor supplies could attach.
	 */
	@Test
	public void matchesBossNamesEndingInS()
	{
		assertTrue(SlayerTaskTargets.matches("Sarachnis", "Sarachnis"));
		assertTrue(SlayerTaskTargets.matches("Venenatis", "Venenatis"));
		assertTrue(SlayerTaskTargets.matches("Cerberus", "Cerberus"));
		assertTrue(SlayerTaskTargets.matches("Vardorvis", "Vardorvis"));
		assertTrue(SlayerTaskTargets.matches("Duke Sucellus", "Duke Sucellus"));
		// The singular strip still has to work for the plurals it exists for.
		assertTrue(SlayerTaskTargets.matches("Spiders", "Spider"));
	}

	/** Assignable as a regular Dagannoth task and as the boss task, which read differently. */
	@Test
	public void matchesDagannothKingsUnderBothAssignments()
	{
		for (String king : new String[]{"Dagannoth Rex", "Dagannoth Prime", "Dagannoth Supreme"})
		{
			assertTrue(SlayerTaskTargets.matches("Dagannoth", king));
			assertTrue(SlayerTaskTargets.matches("Dagannoth Kings", king));
		}
		assertTrue(SlayerTaskTargets.matches("Dagannoth", "Dagannoth"));
		// The boss assignment is the three kings only — an ordinary dagannoth is not one of them.
		assertFalse(SlayerTaskTargets.matches("Dagannoth Kings", "Dagannoth"));
	}

	/**
	 * The three wilderness bosses each have a singles-plus variant that counts for the same
	 * assignment, which is only ever handed out under the main boss's name.
	 */
	@Test
	public void matchesWildernessBossVariants()
	{
		assertTrue(SlayerTaskTargets.matches("Vet'ion", "Calvar'ion"));
		assertTrue(SlayerTaskTargets.matches("Vet'ion", "Vet'ion"));
		// Both bosses fight on in a second form under a longer name.
		assertTrue(SlayerTaskTargets.matches("Vet'ion", "Calvar'ion Reborn"));
		assertTrue(SlayerTaskTargets.matches("Vet'ion", "Vet'ion Reborn"));
		assertTrue(SlayerTaskTargets.matches("Callisto", "Artio"));
		assertTrue(SlayerTaskTargets.matches("Callisto", "Callisto"));
		assertTrue(SlayerTaskTargets.matches("Venenatis", "Spindel"));
		assertTrue(SlayerTaskTargets.matches("Venenatis", "Venenatis"));
		// The variants are not interchangeable across assignments.
		assertFalse(SlayerTaskTargets.matches("Callisto", "Spindel"));
		assertFalse(SlayerTaskTargets.matches("Venenatis", "Artio"));
	}

	/**
	 * A venator counts for a vampyres assignment and shares no word with it, so only an alias can
	 * connect the two. The relation is one-way and the lookup is keyed on the assignment, which
	 * keeps it so: a vampyres task reaches a venator, a venators task reaches only venators.
	 */
	@Test
	public void matchesVenatorsOnAVampyresTask()
	{
		assertTrue(SlayerTaskTargets.matches("Vampyres", "Venator"));
		assertTrue(SlayerTaskTargets.matches("Vampyres", "Blood-starved venator"));
		// The dedicated assignment reaches both on the singular strip, with no key of its own.
		assertTrue(SlayerTaskTargets.matches("Venators", "Venator"));
		assertTrue(SlayerTaskTargets.matches("Venators", "Blood-starved venator"));
		// ...and no further. Vampyres do not count for a venators task.
		assertFalse(SlayerTaskTargets.matches("Venators", "Vyrewatch"));
		assertFalse(SlayerTaskTargets.matches("Venators", "Vyrewatch Sentinel"));
		assertFalse(SlayerTaskTargets.matches("Venators", "Feral Vampyre"));
		assertFalse(SlayerTaskTargets.matches("Venators", "Vampyre Juvinate"));
		// The rest of the vampyres targets, which were never broken.
		assertTrue(SlayerTaskTargets.matches("Vampyres", "Feral Vampyre"));
		assertTrue(SlayerTaskTargets.matches("Vampyres", "Vampyre Juvinate"));
		assertTrue(SlayerTaskTargets.matches("Vampyres", "Vampyre Juvenile"));
		assertTrue(SlayerTaskTargets.matches("Vampyres", "Vyrewatch"));
		assertTrue(SlayerTaskTargets.matches("Vampyres", "Vyrewatch Sentinel"));
	}

	/**
	 * The assignment is handed out as "TzHaar" and the four city monsters are named directly after
	 * it, but only with a hyphen between the race and the caste — which the whole-word matcher read
	 * as part of the word, so the assignment recognised none of its own targets.
	 */
	@Test
	public void matchesTheCityTzhaarAcrossTheHyphen()
	{
		assertTrue(SlayerTaskTargets.matches("TzHaar", "TzHaar-Ket"));
		assertTrue(SlayerTaskTargets.matches("TzHaar", "TzHaar-Xil"));
		assertTrue(SlayerTaskTargets.matches("TzHaar", "TzHaar-Hur"));
		assertTrue(SlayerTaskTargets.matches("TzHaar", "TzHaar-Mej"));
		// The panel titlecases the assignment from the uppercase name the task table holds.
		assertTrue(SlayerTaskTargets.matches("Tzhaar", "TzHaar-Ket"));
		// The named individuals are the same monsters under a third name part.
		assertTrue(SlayerTaskTargets.matches("TzHaar", "TzHaar-Ket-Zuh"));
		assertTrue(SlayerTaskTargets.matches("TzHaar", "TzHaar-Mej-Roh"));
	}

	/**
	 * The Fight Caves and the Inferno are the same slayer category, and nothing in either shares a
	 * word with the assignment, so every one of them needs an alias.
	 */
	@Test
	public void matchesTheFightCaveAndInfernoTzhaar()
	{
		for (String caveMonster : new String[]{
			"Tz-Kih", "Tz-Kek", "Tok-Xil", "Yt-MejKot", "Ket-Zek", "Yt-HurKot", "TzTok-Jad"})
		{
			assertTrue(caveMonster, SlayerTaskTargets.matches("TzHaar", caveMonster));
		}
		for (String infernoMonster : new String[]{
			"Jal-Nib", "Jal-MejRah", "Jal-Ak", "Jal-AkRek-Mej", "Jal-AkRek-Xil", "Jal-AkRek-Ket",
			"Jal-ImKot", "Jal-Xil", "Jal-Zek", "Jal-MejJak", "JalTok-Jad", "TzKal-Zuk"})
		{
			assertTrue(infernoMonster, SlayerTaskTargets.matches("TzHaar", infernoMonster));
		}
		// The blob's spawns are longer names beginning with its own, and the whole-word rule has to
		// keep telling them apart now that the hyphen no longer does.
		assertFalse(SlayerTaskTargets.matches("Jal-Ak", "Jal-AkRek-Mej"));
	}

	/**
	 * Both bosses are also assignable in their own right, and the assignment is then the boss
	 * alone — killing the waves that lead to it does not count towards it.
	 */
	@Test
	public void aJadOrZukAssignmentIsThatBossOnly()
	{
		assertTrue(SlayerTaskTargets.matches("TzTok-Jad", "TzTok-Jad"));
		assertTrue(SlayerTaskTargets.matches("TzKal-Zuk", "TzKal-Zuk"));
		assertFalse(SlayerTaskTargets.matches("TzTok-Jad", "Ket-Zek"));
		assertFalse(SlayerTaskTargets.matches("TzKal-Zuk", "Jal-Zek"));
		assertFalse(SlayerTaskTargets.matches("TzTok-Jad", "TzHaar-Ket"));
	}

	/**
	 * The game titles a boss assignment with an article the NPC's own name does not carry, so
	 * every one of these recognised nothing at all: no session, no loot, no supply cost, while
	 * the name-blind counter kept banking kills. Confirmed rather than assumed — a persisted
	 * record in the profile reads "The Shellbane Gryphon" at 3 counter kills and 0 sessions.
	 */
	@Test
	public void matchesBossAssignmentsTitledWithTheArticle()
	{
		assertTrue(SlayerTaskTargets.matches("The Shellbane Gryphon", "Shellbane gryphon"));
		assertTrue(SlayerTaskTargets.matches("The Abyssal Sire", "Abyssal Sire"));
		assertTrue(SlayerTaskTargets.matches("The Alchemical Hydra", "Alchemical Hydra"));
		assertTrue(SlayerTaskTargets.matches("The Chaos Elemental", "Chaos Elemental"));
		assertTrue(SlayerTaskTargets.matches("The Chaos Fanatic", "Chaos Fanatic"));
		assertTrue(SlayerTaskTargets.matches("The Giant Mole", "Giant Mole"));
		assertTrue(SlayerTaskTargets.matches("The Kalphite Queen", "Kalphite Queen"));
		assertTrue(SlayerTaskTargets.matches("The King Black Dragon", "King Black Dragon"));
		assertTrue(SlayerTaskTargets.matches("The Maggot King", "Maggot King"));
		assertTrue(SlayerTaskTargets.matches("The Phantom Muspah", "Phantom Muspah"));
		assertTrue(SlayerTaskTargets.matches("The Thermonuclear Smoke Devil", "Thermonuclear smoke devil"));
		// The two whose NPC name carries the article too must keep working from the raw name.
		assertTrue(SlayerTaskTargets.matches("The Leviathan", "The Leviathan"));
		assertTrue(SlayerTaskTargets.matches("The Whisperer", "The Whisperer"));
		// Aliases are keyed without the article, and reachable with or without it, because
		// nothing here can prove which spelling the game's task table holds.
		assertTrue(SlayerTaskTargets.matches("The Cave Kraken Boss", "Kraken"));
		assertTrue(SlayerTaskTargets.matches("Cave Kraken Boss", "Kraken"));
		assertTrue(SlayerTaskTargets.matches("The Grotesque Guardians", "Dusk"));
		assertTrue(SlayerTaskTargets.matches("Grotesque Guardians", "Dawn"));
		// Only the assignment loses its article, never the NPC name.
		assertFalse(SlayerTaskTargets.matches("The Giant Mole", "Mole"));
	}

	/** The six brothers are assigned as a group and none of them shares a word with it. */
	@Test
	public void matchesTheBarrowsBrothers()
	{
		for (String brother : new String[]{
			"Ahrim the Blighted", "Dharok the Wretched", "Guthan the Infested",
			"Karil the Tainted", "Torag the Corrupted", "Verac the Defiled"})
		{
			assertTrue(brother, SlayerTaskTargets.matches("Barrows Brothers", brother));
		}
	}

	/**
	 * A named individual is one whole word of something else's name, so it has to match the
	 * NPC exactly. "Rock" is a troll in the Troll Stronghold, and as a whole-word needle it
	 * also matched Rock Crab — a common training spot, on a common Turael task.
	 */
	@Test
	public void namedIndividualsMatchOnlyTheirOwnNpc()
	{
		assertTrue(SlayerTaskTargets.matches("Trolls", "Rock"));
		assertFalse(SlayerTaskTargets.matches("Trolls", "Rock Crab"));
		assertFalse(SlayerTaskTargets.matches("Trolls", "Giant Rock Crab"));
		assertFalse(SlayerTaskTargets.matches("Trolls", "Rock lobster"));
		assertFalse(SlayerTaskTargets.matches("Trolls", "Rock Golem"));
		// The multi-word troll names are unambiguous and stay ordinary aliases.
		assertTrue(SlayerTaskTargets.matches("Trolls", "Chuck up"));
		assertTrue(SlayerTaskTargets.matches("Trolls", "The rocks"));
		// A monkeys assignment reaches the Ape Atoll guard called Duke, and stops there.
		assertTrue(SlayerTaskTargets.matches("Monkeys", "Duke"));
		assertFalse(SlayerTaskTargets.matches("Monkeys", "Duke Sucellus"));
		// ...and against the spawn, which carries no slayer category of its own.
		assertTrue(SlayerTaskTargets.matches("Lesser demons", "Reanimated demon"));
		assertFalse(SlayerTaskTargets.matches("Lesser demons", "Reanimated demon spawn"));
	}

	/**
	 * Targets found by sweeping every assignment against the wiki's per-monster slayer
	 * category, each one a monster that shares no word with the assignment it counts for.
	 */
	@Test
	public void matchesTargetsThatShareNoWordWithTheirAssignment()
	{
		assertTrue(SlayerTaskTargets.matches("Basilisks", "The Jormungand"));
		assertTrue(SlayerTaskTargets.matches("Basilisks", "Typhor"));
		assertTrue(SlayerTaskTargets.matches("Chaos druids", "Salarin the twisted"));
		assertTrue(SlayerTaskTargets.matches("Crazy Archaeologists", "Deranged archaeologist"));
		assertTrue(SlayerTaskTargets.matches("Dogs", "Shadow Hound"));
		assertTrue(SlayerTaskTargets.matches("Elves", "Mourner"));
		assertTrue(SlayerTaskTargets.matches("Ghosts", "Treus Dayth"));
		assertTrue(SlayerTaskTargets.matches("Goblins", "Wormbrain"));
		assertTrue(SlayerTaskTargets.matches("Greater demons", "Judge of Yama"));
		assertTrue(SlayerTaskTargets.matches("Hellhounds", "Bouncer"));
		assertTrue(SlayerTaskTargets.matches("Ice warriors", "Kamil"));
		assertTrue(SlayerTaskTargets.matches("Lesser Nagua", "Earthen Nagua"));
		assertTrue(SlayerTaskTargets.matches("Ogres", "Gorad"));
		assertTrue(SlayerTaskTargets.matches("Scorpions", "Scorpia's guardian"));
		assertTrue(SlayerTaskTargets.matches("Skeletons", "Ulfric"));
		assertTrue(SlayerTaskTargets.matches("Vampyres", "Ranis Drakan"));
		assertTrue(SlayerTaskTargets.matches("Zombies", "Slash Bash"));
		assertTrue(SlayerTaskTargets.matches("Abyssal demons", "Respiratory system"));
		assertTrue(SlayerTaskTargets.matches("The Abyssal Sire", "Respiratory system"));
		// One alias covers the superior and the infernal one, both being pyrelords by name.
		assertTrue(SlayerTaskTargets.matches("Pyrefiends", "Pyrelord"));
		assertTrue(SlayerTaskTargets.matches("Pyrefiends", "Flaming pyrelord"));
		assertTrue(SlayerTaskTargets.matches("Pyrefiends", "Infernal pyrelord"));
	}

	/**
	 * The scabarite scarabs are listed by name rather than under a bare "Scarab", which would
	 * also take the Tombs of Amascut scarabs — none of which carries a slayer category.
	 */
	@Test
	public void scarabsDoNotReachTheTombsOfAmascut()
	{
		assertTrue(SlayerTaskTargets.matches("Scabarites", "Giant Scarab"));
		assertTrue(SlayerTaskTargets.matches("Scabarites", "Scarabs"));
		assertTrue(SlayerTaskTargets.matches("Scabarites", "Scarab Mage"));
		assertTrue(SlayerTaskTargets.matches("Scabarites", "Small scarab"));
		assertFalse(SlayerTaskTargets.matches("Scabarites", "Soldier Scarab"));
		assertFalse(SlayerTaskTargets.matches("Scabarites", "Spitting Scarab"));
		assertFalse(SlayerTaskTargets.matches("Scabarites", "Agile Scarab"));
		assertFalse(SlayerTaskTargets.matches("Scabarites", "Arcane Scarab"));
	}

	/** The game spells the apostrophe both ways; neither may decide whether a kill counts. */
	@Test
	public void toleratesTypographicApostrophes()
	{
		assertTrue(SlayerTaskTargets.matches("Vet\u2019ion", "Calvar'ion"));
		assertTrue(SlayerTaskTargets.matches("Vet'ion", "Calvar\u2019ion"));
	}

	@Test
	public void usesWholeWordsAndRejectsUnrelatedNpcs()
	{
		assertFalse(SlayerTaskTargets.matches("Smoke devils", "Dust devil"));
		assertFalse(SlayerTaskTargets.matches("Dogs", "Underdog"));
		assertFalse(SlayerTaskTargets.matches("Araxytes", "Spider"));
	}
}

package com.slayertaskloot;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class DropExclusionsTest
{
	@Test
	public void globalExclusionAppliesToEveryTask()
	{
		final String global = DropExclusions.addGlobal("Coins", "Fire rune");
		assertTrue(DropExclusions.isExcluded(global, "", "Abyssal demons", "fire RUNE"));
		assertTrue(DropExclusions.isExcluded(global, "", "Gargoyles", "Fire rune"));
		assertFalse(DropExclusions.isExcluded(global, "", "Gargoyles", "Air rune"));
	}

	@Test
	public void taskExclusionOnlyAppliesToNamedTask()
	{
		final String perTask = DropExclusions.addForTask(
			"Gargoyles = Coins", "Abyssal demons", "Fire rune");
		assertTrue(DropExclusions.isExcluded("", perTask, "Abyssal demons", "Fire rune"));
		assertFalse(DropExclusions.isExcluded("", perTask, "Gargoyles", "Fire rune"));
	}

	@Test
	public void addingSameExclusionIsIdempotent()
	{
		final String once = DropExclusions.addForTask("", "Dust devils", "Fire rune");
		final String twice = DropExclusions.addForTask(once, "dust  devils", "fire RUNE");
		assertTrue(once.equals(twice));
	}

	@Test
	public void exclusionsCanBeRemovedWithoutDisturbingOtherEntries()
	{
		final String global = DropExclusions.removeGlobal("Coins; Hydra bones; Fire rune", "hydra BONES");
		assertFalse(DropExclusions.isExcluded(global, "", "Hydras", "Hydra bones"));
		assertTrue(DropExclusions.isExcluded(global, "", "Hydras", "Coins"));

		final String perTask = DropExclusions.removeForTask(
			"Hydras = Hydra bones; Gargoyles = Coins; Hydras = Coins", "hydras", "HYDRA bones");
		assertFalse(DropExclusions.isExcluded("", perTask, "Hydras", "Hydra bones"));
		assertTrue(DropExclusions.isExcluded("", perTask, "Hydras", "Coins"));
		assertTrue(DropExclusions.isExcluded("", perTask, "Gargoyles", "Coins"));
	}

	@Test
	public void taskEntriesOnlyExposeTheSelectedTask()
	{
		final String perTask = "Hydras = Hydra bones; Gargoyles = Coins; Hydras = Coins";
		assertTrue(DropExclusions.entriesForTask(perTask, "Hydras").size() == 2);
		assertTrue(DropExclusions.entriesForTask(perTask, "Hydras").contains("Hydra bones"));
		assertFalse(DropExclusions.entriesForTask(perTask, "Hydras").contains("Gargoyles = Coins"));
	}

	@Test
	public void perTaskEntriesAreGroupedByTask()
	{
		String value = DropExclusions.addForTask("Hydras = Hydra bones", "Hydras", "Coins");
		value = DropExclusions.addForTask(value, "Gargoyles", "Granite maul");
		assertEquals("Hydras: Hydra bones, Coins; Gargoyles: Granite maul", value);
		assertTrue(DropExclusions.isExcluded("", value, "Hydras", "Coins"));
		assertTrue(DropExclusions.isExcluded("", value, "Gargoyles", "Granite maul"));
	}

	@Test
	public void legacyPerTaskEntriesMigrateWithoutLosingItems()
	{
		assertEquals("Hydras: Hydra bones, Coins; Gargoyles: Coins",
			DropExclusions.formatPerTask(
				"Hydras = Hydra bones; Hydras = Coins; Gargoyles = Coins"));
	}
}

package com.slayertaskloot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Covers component quantities being held in hundredths of an item, so that a use spending a
 * fraction of one is visible in the breakdown at the moment it happens.
 *
 * <p>The bug this exists for: a scythe swing spends a hundredth of a vial of blood, which as a
 * whole-item count rounded to nothing. The vial then only appeared on every hundredth swing, so a
 * forty-swing task listed blood runes and no vial — while the vial's cost was in the row's total
 * the whole time. A supply that is tracked but invisible reads exactly like one that isn't
 * tracked, and was reported as such twice.
 */
public class SupplyComponentTest
{
	@Test
	public void aFractionOfAnItemIsListedRatherThanRoundedAway()
	{
		assertEquals("0.01", SlayerTaskLootPlugin.componentQuantity(1));
		assertEquals("0.4", SlayerTaskLootPlugin.componentQuantity(40));
		assertEquals("2.5", SlayerTaskLootPlugin.componentQuantity(250));
		assertEquals("1.05", SlayerTaskLootPlugin.componentQuantity(105));
	}

	@Test
	public void wholeQuantitiesKeepThePanelsAbbreviatedForm()
	{
		assertEquals("2", SlayerTaskLootPlugin.componentQuantity(200));
		assertEquals("1,200", SlayerTaskLootPlugin.componentQuantity(120_000));
		assertEquals("15K", SlayerTaskLootPlugin.componentQuantity(1_500_000));
	}

	@Test
	public void fractionsAccumulateAcrossUses()
	{
		final SupplyEntry entry = new SupplyEntry(1, 80, false,
			Collections.singletonMap(ItemID.VIAL_BLOOD, 1));
		for (int swing = 2; swing <= 40; swing++)
		{
			entry.add(1, 80, Collections.singletonMap(ItemID.VIAL_BLOOD, 1));
		}

		// Forty swings is four tenths of a vial, and says so, rather than waiting for the
		// hundredth swing to show a whole one.
		assertEquals(40, (int) entry.getComponentHundredths().get(ItemID.VIAL_BLOOD));
		assertEquals("0.4", SlayerTaskLootPlugin.componentQuantity(
			entry.getComponentHundredths().get(ItemID.VIAL_BLOOD)));
		assertTrue(entry.isCharged());
	}

	@Test
	public void recordsWrittenInWholeItemsMigrateOnRead()
	{
		// A stored record predating hundredths holds whole items. Reading it as hundredths
		// unchanged would shrink every historic breakdown a hundredfold.
		final SupplyEntry legacy = legacyEntry(Collections.singletonMap(ItemID.BLOODRUNE, 12));

		assertEquals(1200, (int) legacy.getComponentHundredths().get(ItemID.BLOODRUNE));
		assertEquals("12", SlayerTaskLootPlugin.componentQuantity(
			legacy.getComponentHundredths().get(ItemID.BLOODRUNE)));
		assertTrue(legacy.isCharged());
	}

	@Test
	public void aMigratedRecordKeepsItsComponentsWhenAddedTo()
	{
		final SupplyEntry legacy = legacyEntry(Collections.singletonMap(ItemID.BLOODRUNE, 12));
		legacy.add(1, 80, Collections.singletonMap(ItemID.BLOODRUNE, 200));

		// The pre-existing 12 must survive the switch to the new field rather than restarting.
		assertEquals(1400, (int) legacy.getComponentHundredths().get(ItemID.BLOODRUNE));
	}

	/** A record deserialised from before components were held in hundredths. */
	private static SupplyEntry legacyEntry(Map<Integer, Integer> wholeItems)
	{
		final SupplyEntry entry = new SupplyEntry(1, 80, false);
		try
		{
			final java.lang.reflect.Field field = SupplyEntry.class.getDeclaredField("components");
			field.setAccessible(true);
			field.set(entry, new LinkedHashMap<>(wholeItems));
		}
		catch (ReflectiveOperationException ex)
		{
			throw new AssertionError(ex);
		}
		return entry;
	}
}

package com.slayertaskloot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import org.junit.Test;

public class TaskSessionTest
{
	@Test
	public void manualResumeAddsSegmentToSameSession()
	{
		final TaskLootRecord task = new TaskLootRecord("Smoke devils", null, 150, 1L);
		final TaskSession session = task.openNewSession(10L, false);
		task.tickSession(session.getSessionId());
		task.closeSession(session.getSessionId(), 20L, "IDLE_TIMEOUT");

		task.resumeSession(session.getSessionId(), 30L);
		task.tickSession(session.getSessionId());
		task.closeSession(session.getSessionId(), 40L, "MANUAL");

		assertEquals(1, task.getSessions());
		assertEquals(2, session.getSegments().size());
		assertEquals(2, task.getOnTaskTicks());
		assertFalse(session.isOpen());
	}

	/**
	 * The tick loop repairs this rather than absorbing it. A reload closing the record's
	 * sessions while the plugin still believed one was open used to stop the panel clock for
	 * good, since opening is guarded on that same belief.
	 */
	@Test
	public void tickingReportsWhenTheSessionIsNotActuallyOpen()
	{
		final TaskLootRecord task = new TaskLootRecord("Smoke devils", null, 150, 1L);
		final TaskSession session = task.openNewSession(10L, false);

		assertTrue(task.tickSession(session.getSessionId()));
		assertFalse(task.tickSession("a session this task has never held"));

		task.closeOpenSessions(20L, "CLIENT_RESTART");
		assertFalse(task.tickSession(session.getSessionId()));
		assertEquals(1, task.getOnTaskTicks());

		task.resumeSession(session.getSessionId(), 30L);
		assertTrue(task.tickSession(session.getSessionId()));
		assertEquals(2, task.getOnTaskTicks());
	}

	@Test
	public void automaticOpenCreatesDistinctSession()
	{
		final TaskLootRecord task = new TaskLootRecord("Smoke devils", null, 150, 1L);
		final TaskSession first = task.openNewSession(10L, false);
		task.closeSession(first.getSessionId(), 20L, "IDLE_TIMEOUT");
		final TaskSession second = task.openNewSession(30L, false);

		assertEquals(2, task.getSessions());
		assertNotEquals(first.getSessionId(), second.getSessionId());
		assertTrue(second.isOpen());
	}

	@Test
	public void closedSessionsCanBeMergedWithoutLosingSegments()
	{
		final TaskLootRecord task = new TaskLootRecord("Smoke devils", null, 150, 1L);
		final TaskSession first = task.openNewSession(10L, false);
		task.closeSession(first.getSessionId(), 20L, "MANUAL");
		final TaskSession second = task.openNewSession(30L, false);
		task.closeSession(second.getSessionId(), 40L, "MANUAL");

		assertTrue(task.mergeSessions(first.getSessionId(), second.getSessionId()));
		assertEquals(1, task.getSessions());
		assertEquals(2, first.getSegments().size());
	}

	@Test
	public void legacySessionTotalsRemainAsMigrationBaseline()
	{
		final TaskLootRecord task = new Gson().fromJson(
			"{\"taskName\":\"Smoke devils\",\"sessions\":2,\"onTaskTicks\":50}",
			TaskLootRecord.class);
		final TaskSession current = task.openNewSession(10L, true);
		task.tickSession(current.getSessionId());

		assertEquals(3, task.getSessions());
		assertEquals(51, task.getOnTaskTicks());
	}

	@Test
	public void mergingSessionsPoolsKillsLootAndSupplies()
	{
		final TaskLootRecord task = new TaskLootRecord("Smoke devils", null, 150, 1L);
		final TaskSession first = task.openNewSession(10L, false);
		task.addKills(first.getSessionId(), 2);
		task.addItem(first.getSessionId(), 995, 100, 100);
		task.addSupplyCharge(first.getSessionId(), new SupplyCharge(30,
			java.util.List.of(new SupplyCharge.Row(565, 3, 30, false))));
		task.closeSession(first.getSessionId(), 20L, "MANUAL");

		final TaskSession second = task.openNewSession(30L, false);
		task.addKills(second.getSessionId(), 3);
		task.addItem(second.getSessionId(), 995, 200, 200);
		task.addSupplyCharge(second.getSessionId(), new SupplyCharge(20,
			java.util.List.of(new SupplyCharge.Row(565, 2, 20, false))));
		task.closeSession(second.getSessionId(), 40L, "MANUAL");

		assertTrue(task.mergeSessions(first.getSessionId(), second.getSessionId()));
		assertEquals(5, task.getKills());
		assertEquals(Integer.valueOf(300), task.getItems().get(995));
		assertEquals(Long.valueOf(300), task.getItemValues().get(995));
		assertEquals(50, task.getSupplyCost());
		assertEquals(5, task.getSupplies().get(565).getQuantity());
	}

	/**
	 * The counter is the only exact kill signal, so a kill it banked has to survive the death
	 * match failing. This is the 311-vs-253 case: every kill moved the counter, but a despawn
	 * seen outside the two-tick window matched nothing and used to be discarded outright.
	 */
	@Test
	public void countedKillsSurviveTheDeathMatchFailing()
	{
		final TaskLootRecord task = new TaskLootRecord("Gargoyles", null, 311, 1L);
		final TaskSession session = task.openNewSession(10L, false);

		for (int i = 0; i < 311; i++)
		{
			task.addCounterKills(1);
		}
		// Only some of those could be tied to a death the client saw in time.
		task.addKills(session.getSessionId(), 253);

		assertEquals(311, task.getKills());
		assertEquals(253, task.getAttributedKills());
	}

	/** They count the same kills by different means, so the total is the larger, never the sum. */
	@Test
	public void countedAndAttributedKillsAreNotAddedTogether()
	{
		final TaskLootRecord task = new TaskLootRecord("Gargoyles", null, 100, 1L);
		final TaskSession session = task.openNewSession(10L, false);
		task.addCounterKills(40);
		task.addKills(session.getSessionId(), 40);

		assertEquals(40, task.getKills());
	}

	/**
	 * A death can be credited with no counter movement to pair with — loot arriving for a kill
	 * the counter banked earlier does exactly that — so the attributed side has to be able to lead.
	 */
	@Test
	public void attributedKillsLeadWhenTheyExceedTheCounter()
	{
		final TaskLootRecord task = new TaskLootRecord("Gargoyles", null, 100, 1L);
		final TaskSession session = task.openNewSession(10L, false);
		task.addCounterKills(2);
		task.addKills(session.getSessionId(), 5);

		assertEquals(5, task.getKills());
	}

	/** Records stored before the counter total existed carry only the attributed side. */
	@Test
	public void storedRecordWithoutACounterTotalKeepsItsKills()
	{
		final TaskLootRecord task = new Gson().fromJson(
			"{\"taskName\":\"Gargoyles\",\"kills\":47}", TaskLootRecord.class);

		assertEquals(47, task.getKills());
		assertEquals(47, task.getAttributedKills());
	}

	@Test
	public void mergingRecordsPoolsCountedKills()
	{
		final TaskLootRecord active = new TaskLootRecord("Gargoyles", null, 100, 20L);
		active.addCounterKills(30);

		final TaskLootRecord historical = new TaskLootRecord("Gargoyles", null, 90, 1L);
		historical.addCounterKills(12);
		historical.setEndedAt(10L);

		active.mergeRecord(historical);

		assertEquals(42, active.getKills());
	}

	@Test
	public void historicalRecordCanBePooledIntoActiveMatchingTask()
	{
		final TaskLootRecord active = new TaskLootRecord("Custodian stalkers", null, 104, 20L);
		final TaskSession activeSession = active.openNewSession(20L, false);
		active.addKills(activeSession.getSessionId(), 2);

		final TaskLootRecord historical = new TaskLootRecord("Custodian stalkers", null, 90, 1L);
		final TaskSession oldSession = historical.openNewSession(1L, false);
		historical.addKills(oldSession.getSessionId(), 5);
		historical.addItem(oldSession.getSessionId(), 995, 100, 100);
		historical.closeSession(oldSession.getSessionId(), 10L, "COMPLETED");
		historical.setEndedAt(10L);

		active.mergeRecord(historical);

		assertEquals(7, active.getKills());
		assertEquals(2, active.getSessions());
		assertEquals(194, active.getInitialAmount());
		assertEquals(Integer.valueOf(100), active.getItems().get(995));
		assertFalse(active.isCompleted());
	}
}

package com.slayertaskloot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntFunction;
import org.junit.Test;

/**
 * Dose netting across every potion family a task is likely to involve, rather than the one it was
 * developed against.
 *
 * <p>Prayer potion proves less than it looks. Its name is the plainest shape a dose family can
 * have, and passing on it says nothing about the ones that differ: a hyphen ("Anti-venom"), a
 * trailing plus that another family is a prefix of ("Antidote+" against "Antidote++"), no space
 * before the dose ("Superantipoison"), a space before it and a number inside the base
 * ("Serum 207"), and a sibling separated only by that number ("Serum 208").
 *
 * <p>Ids and names are transcribed from RuneLite's own {@code ItemID} javadoc and
 * {@code item_variations.json}, so a family regrouped upstream fails here rather than quietly
 * ceasing to net in game.
 *
 * <p>What makes this exercise the variation lookup rather than the arithmetic: nothing but the
 * 3-dose container ever drops, so the 1-dose the remainder is repacked into is reachable only
 * through {@link net.runelite.client.game.ItemVariationMapping}. A family missing from that table
 * leaves the remainder with no container to go into.
 */
public class TaskNettingDoseFamiliesTest
{
	/**
	 * The exact prefix the game puts before the dose, then the ids of the 1-, 2-, 3- and 4-dose
	 * containers. Two families really do carry a space there — "Serum 207 (4)" and "Overload (4)"
	 * against "Prayer potion(4)" — so the prefix is stored verbatim rather than synthesised, and
	 * the trailing space in those two rows is deliberate.
	 */
	private static final Object[][] FOUR_DOSE = {
		{"Prayer potion", 143, 141, 139, 2434},
		{"Super restore", 3030, 3028, 3026, 3024},
		{"Saradomin brew", 6691, 6689, 6687, 6685},
		{"Super combat potion", 12701, 12699, 12697, 12695},
		{"Divine super combat potion", 23694, 23691, 23688, 23685},
		{"Ranging potion", 173, 171, 169, 2444},
		{"Divine ranging potion", 23742, 23739, 23736, 23733},
		{"Stamina potion", 12631, 12629, 12627, 12625},
		{"Antidote+", 5949, 5947, 5945, 5943},
		{"Antidote++", 5958, 5956, 5954, 5952},
		{"Anti-venom", 12911, 12909, 12907, 12905},
		{"Anti-venom+", 12919, 12917, 12915, 12913},
		{"Antipoison", 179, 177, 175, 2446},
		{"Superantipoison", 185, 183, 181, 2448},
		{"Super antifire potion", 21987, 21984, 21981, 21978},
		{"Extended super antifire", 22218, 22215, 22212, 22209},
		{"Sanfew serum", 10931, 10929, 10927, 10925},
		{"Serum 207 ", 3414, 3412, 3410, 3408},
		{"Serum 208 ", 3419, 3418, 3417, 3416},
		{"Super energy", 3022, 3020, 3018, 3016},
		{"Super attack", 149, 147, 145, 2436},
		{"Super strength", 161, 159, 157, 2440},
		{"Magic potion", 3046, 3044, 3042, 3040},
		{"Ancient brew", 26346, 26344, 26342, 26340},
		{"Forgotten brew", 27638, 27635, 27632, 27629},
		{"Menaphite remedy", 27211, 27208, 27205, 27202},
		{"Moonlight potion", 29083, 29082, 29081, 29080},
		{"Goading potion", 30146, 30143, 30140, 30137},
		{"Zamorak brew", 193, 191, 189, 2450},
		{"Bastion potion", 22470, 22467, 22464, 22461},
		{"Battlemage potion", 22458, 22455, 22452, 22449},
		{"Blighted super restore", 24605, 24603, 24601, 24598},
		{"Guthix rest", 4423, 4421, 4419, 4417},
		{"Overload ", 11733, 11732, 11731, 11730},
	};

	/** Mixes and other two-dose families, which have no 3- or 4-dose container at all. */
	private static final Object[][] TWO_DOSE = {
		{"Prayer mix", 11467, 11465},
		{"Super restore mix", 11495, 11493},
		{"Antidote+ mix", 11503, 11501},
	};

	private static final Map<Integer, String> NAME_MAP = new HashMap<>();
	private static final IntFunction<String> NAMES =
		id -> NAME_MAP.getOrDefault(id, "Item #" + id);

	static
	{
		for (Object[] family : FOUR_DOSE)
		{
			name(family, 4);
		}
		for (Object[] family : TWO_DOSE)
		{
			name(family, 2);
		}
	}

	private static void name(Object[] family, int largest)
	{
		for (int dose = 1; dose <= largest; dose++)
		{
			NAME_MAP.put((Integer) family[dose], family[0] + "(" + dose + ")");
		}
	}

	/**
	 * A 3-dose drops and two of its doses are drunk, charged under the 4-dose container the way
	 * {@code SupplyTracker} stores it. One dose is left, so Drops must read a 1-dose — a container
	 * that never dropped — and the supply row must go entirely.
	 */
	@Test
	public void everyFourDoseFamilyCancelsAcrossVariantsAndRepacksTheRemainder()
	{
		for (Object[] family : FOUR_DOSE)
		{
			final String base = ((String) family[0]).trim();
			final int one = (Integer) family[1];
			final int three = (Integer) family[3];
			final int four = (Integer) family[4];

			final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
			supplies.put(four, new SupplyEntry(2, 200L, true));
			final TaskNetting.Result result = TaskNetting.apply(
				Map.of(three, 1), Map.of(three, 300L), supplies, NAMES);

			assertFalse(base, result.getLootQuantities().containsKey(three));
			assertEquals(base, Integer.valueOf(1), result.getLootQuantities().get(one));
			assertEquals(base, Long.valueOf(100L), result.getLootValues().get(one));
			assertFalse(base, result.getSupplies().containsKey(four));
		}
	}

	/** The same one container down: a 2-dose drops and a single dose is drunk. */
	@Test
	public void everyTwoDoseFamilyCancelsAndRepacksTheRemainder()
	{
		for (Object[] family : TWO_DOSE)
		{
			final String base = ((String) family[0]).trim();
			final int one = (Integer) family[1];
			final int two = (Integer) family[2];

			final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
			supplies.put(two, new SupplyEntry(1, 100L, true));
			final TaskNetting.Result result = TaskNetting.apply(
				Map.of(two, 1), Map.of(two, 200L), supplies, NAMES);

			assertEquals(base, Integer.valueOf(1), result.getLootQuantities().get(one));
			assertEquals(base, Long.valueOf(100L), result.getLootValues().get(one));
			assertFalse(base, result.getSupplies().containsKey(two));
		}
	}

	/**
	 * Families whose names are prefixes of one another must never pool. Both pairs are real: the
	 * antidotes differ by a single trailing character, and the serums only by the number carried
	 * inside the base name.
	 */
	@Test
	public void familiesWithPrefixNamesNeverCancelAgainstEachOther()
	{
		assertNoCrossCancel("Antidote+", "Antidote++");
		assertNoCrossCancel("Antidote++", "Antidote+");
		assertNoCrossCancel("Serum 207", "Serum 208");
	}

	private static void assertNoCrossCancel(String droppedBase, String drunkBase)
	{
		final int dropped = (Integer) family(droppedBase)[4];
		final int drunk = (Integer) family(drunkBase)[4];

		final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
		supplies.put(drunk, new SupplyEntry(4, 400L, true));
		final TaskNetting.Result result = TaskNetting.apply(
			Map.of(dropped, 1), Map.of(dropped, 400L), supplies, NAMES);

		final String message = droppedBase + " dropped against " + drunkBase + " drunk";
		assertEquals(message, Integer.valueOf(1), result.getLootQuantities().get(dropped));
		assertEquals(message, 4, result.getSupplies().get(drunk).getQuantity());
	}

	private static Object[] family(String base)
	{
		for (Object[] candidate : FOUR_DOSE)
		{
			if (base.equals(((String) candidate[0]).trim()))
			{
				return candidate;
			}
		}
		throw new AssertionError("no such family: " + base);
	}
}

package com.slayertaskloot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.IntFunction;
import org.junit.Test;

/**
 * Food eaten in halves and slices, which is counted in portions for the same reason a potion is
 * counted in doses.
 *
 * <p>The bug this covers was reported from an Araxxor task: three wild pies eaten, and the panel
 * showed the three pies that dropped at their full price in Drops with "Half a wild pie x3" at
 * 0 gp in Supplies. Both halves of that come from counting the pie in items. Eating a whole pie
 * is one pie out and one half in — equal item counts, which the transformation guard reads as a
 * trident being recharged rather than as food being eaten, so the bite isn't billed at all; the
 * last bite then bills the untradeable half at the only price it has, which is nothing.
 */
public class PortionFoodTest
{
	private static final int WILD_PIE = 7208;
	private static final int HALF_A_WILD_PIE = 7210;

	private static final Map<Integer, String> NAME_MAP = new HashMap<>();
	private static final IntFunction<String> NAMES =
		id -> NAME_MAP.getOrDefault(id, "Item #" + id);

	static
	{
		NAME_MAP.put(WILD_PIE, "Wild pie");
		NAME_MAP.put(HALF_A_WILD_PIE, "Half a wild pie");
	}

	@Test
	public void piesPizzasAndCakesAreCountedInThePartsTheyAreEatenIn()
	{
		assertEquals(2, SupplyTracker.portionCount("Wild pie"));
		assertEquals(1, SupplyTracker.portionCount("Half a wild pie"));
		// The article follows the word that precedes it, and one family really does take "an".
		assertEquals(1, SupplyTracker.portionCount("Half an admiral pie"));
		assertEquals(2, SupplyTracker.portionCount("Summer pie"));
		assertEquals(2, SupplyTracker.portionCount("Plain pizza"));
		assertEquals(1, SupplyTracker.portionCount("1/2 plain pizza"));
		assertEquals(3, SupplyTracker.portionCount("Cake"));
		assertEquals(2, SupplyTracker.portionCount("2/3 cake"));
		assertEquals(1, SupplyTracker.portionCount("Slice of cake"));
		assertEquals(3, SupplyTracker.portionCount("Chocolate cake"));
		assertEquals(2, SupplyTracker.portionCount("2/3 chocolate cake"));
		assertEquals(1, SupplyTracker.portionCount("Chocolate slice"));
	}

	/** Anything eaten in one bite is counted in items, and most food is. */
	@Test
	public void foodEatenInOneBiteIsNotPortioned()
	{
		assertEquals(0, SupplyTracker.portionCount("Shark"));
		assertEquals(0, SupplyTracker.portionCount("Anglerfish"));
		assertEquals(0, SupplyTracker.portionCount("Cooked karambwan"));
		// Wide enough to catch any cake would catch this one, which is a single bite of poison.
		assertEquals(0, SupplyTracker.portionCount("Dwarven rock cake"));
		assertEquals(0, SupplyTracker.portionCount("Prayer potion(4)"));
		assertEquals(0, SupplyTracker.portionCount(""));
		assertEquals(0, SupplyTracker.portionCount(null));
	}

	/**
	 * Both halves of a pie resolve to the same family, which is what puts them in one row and
	 * lets the whole pie's price cover the bite.
	 */
	@Test
	public void bothHalvesShareTheWholeFoodAsTheirFamily()
	{
		assertEquals("wild pie", SupplyTracker.doseBaseName("Wild pie"));
		assertEquals("wild pie", SupplyTracker.doseBaseName("Half a wild pie"));
		assertEquals("cake", SupplyTracker.doseBaseName("2/3 cake"));
		assertEquals("cake", SupplyTracker.doseBaseName("Slice of cake"));
		assertEquals("chocolate cake", SupplyTracker.doseBaseName("Chocolate slice"));
		assertNull(SupplyTracker.doseBaseName("Shark"));
		// Doses are untouched by any of this.
		assertEquals("Prayer potion", SupplyTracker.doseBaseName("Prayer potion(4)"));
		assertEquals(4, SupplyTracker.unitsPerItem("Prayer potion(4)"));
		assertEquals(2, SupplyTracker.unitsPerItem("Wild pie"));
		assertEquals(0, SupplyTracker.unitsPerItem("Shark"));
	}

	/**
	 * The reported case, netted: three wild pies dropped and all three eaten leaves nothing in
	 * either column, where before it left the drops at full price and a 0 gp row beneath them.
	 */
	@Test
	public void piesEatenCancelAgainstThePiesThatDropped()
	{
		final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
		supplies.put(WILD_PIE, new SupplyEntry(6, 2004L, true));

		final TaskNetting.Result result = TaskNetting.apply(
			Map.of(WILD_PIE, 3), Map.of(WILD_PIE, 2004L), supplies, NAMES);

		assertFalse(result.getLootQuantities().containsKey(WILD_PIE));
		assertFalse(result.getSupplies().containsKey(WILD_PIE));
	}

	/**
	 * A pie and a half eaten out of three dropped leaves a pie and a half, expressed as the
	 * containers the player is actually holding.
	 */
	@Test
	public void theRemainderIsRepackedIntoWholePiesAndHalves()
	{
		final Map<Integer, SupplyEntry> supplies = new LinkedHashMap<>();
		supplies.put(WILD_PIE, new SupplyEntry(3, 1002L, true));

		final TaskNetting.Result result = TaskNetting.apply(
			Map.of(WILD_PIE, 3), Map.of(WILD_PIE, 2004L), supplies, NAMES);

		assertEquals(Integer.valueOf(1), result.getLootQuantities().get(WILD_PIE));
		assertEquals(Integer.valueOf(1), result.getLootQuantities().get(HALF_A_WILD_PIE));
		assertEquals(Long.valueOf(668L), result.getLootValues().get(WILD_PIE));
		assertEquals(Long.valueOf(334L), result.getLootValues().get(HALF_A_WILD_PIE));
		assertFalse(result.getSupplies().containsKey(WILD_PIE));
	}
}

package com.slayertaskloot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

/**
 * Covers the dose-suffix parsing that decides which items get folded into one family.
 *
 * <p>A false positive here would misprice a supply by up to 4x, so the parenthesised names
 * that <em>aren't</em> doses matter as much as the ones that are.
 */
public class SupplyTrackerTest
{
	@Test
	public void prayerRemainsAreNotSupplies()
	{
		assertTrue(SupplyTracker.hasPrayerRemainsAction(
			new String[] {"Scatter", null, null, null, "Drop"}));
		assertTrue(SupplyTracker.hasPrayerRemainsAction(
			new String[] {"Bury", null, null, null, "Drop"}));
		assertFalse(SupplyTracker.hasPrayerRemainsAction(
			new String[] {"Eat", null, null, null, "Drop"}));
		assertFalse(SupplyTracker.hasPrayerRemainsAction(null));
		assertTrue(SupplyTracker.isLootOnlyName("Malicious ashes"));
		assertTrue(SupplyTracker.isLootOnlyName("Dragon bones"));
		assertTrue(SupplyTracker.isLootOnlyName("Ensouled abyssal head"));
		assertFalse(SupplyTracker.isLootOnlyName("Ashes"));
		assertFalse(SupplyTracker.isLootOnlyName("Soda ash"));
		assertFalse(SupplyTracker.isLootOnlyName("Shark"));
		assertFalse(SupplyTracker.isLootOnlyName("Headless arrow"));
		// Untradeable loot that is spent rather than bought. Billed, the removal posts a 0 gp row,
		// netting cancels it against the drop, and both rows are deleted — which is how a polished
		// tarnished spear left no trace of itself or of the rune spear it became.
		assertTrue(SupplyTracker.isLootOnlyName("Tarnished spear"));
		assertTrue(SupplyTracker.isLootOnlyName("Tarnished necklace"));
		assertTrue(SupplyTracker.isLootOnlyName("Venator heart"));
		// What it polishes into is an ordinary item and must still bill if it is ever used.
		assertFalse(SupplyTracker.isLootOnlyName("Rune spear"));
		assertFalse(SupplyTracker.isLootOnlyName("Venator bow"));
	}

	/**
	 * The game is not consistent about the space before the dose, and the price lookup used to
	 * rebuild the name as base + "(4)" — which matched "Prayer potion(4)" and missed
	 * "Serum 207 (4)" and "Overload (4)", dropping those families out of dose netting entirely.
	 */
	@Test
	public void doseBaseNameToleratesTheSpaceBeforeTheDose()
	{
		assertEquals("Prayer potion", SupplyTracker.doseBaseName("Prayer potion(4)"));
		assertEquals("Serum 207", SupplyTracker.doseBaseName("Serum 207 (4)"));
		assertEquals("Overload", SupplyTracker.doseBaseName("Overload (4)"));
		assertEquals("Anti-venom+", SupplyTracker.doseBaseName("Anti-venom+(2)"));
		assertEquals("Antidote++", SupplyTracker.doseBaseName("Antidote++(1)"));
		assertNull(SupplyTracker.doseBaseName("Shark"));
		assertNull(SupplyTracker.doseBaseName("(4)"));
		// Charged jewellery carries a numeric suffix too, so this parses it like any other. The
		// name is not what keeps a ring out of potion normalisation — the Drink action is.
		assertEquals("Ring of dueling", SupplyTracker.doseBaseName("Ring of dueling(8)"));
	}

	@Test
	public void bonesAndAshesAreSeparableFromEnsouledHeads()
	{
		// The bones/ashes toggle moves one of these two groups and not the other: remains can be
		// spent for prayer experience, where an ensouled head is loot however the setting reads.
		assertTrue(SupplyTracker.isPrayerRemainsName("Dragon bones"));
		assertTrue(SupplyTracker.isPrayerRemainsName("Malicious ashes"));
		assertFalse(SupplyTracker.isPrayerRemainsName("Ensouled abyssal head"));

		assertTrue(SupplyTracker.isEnsouledHeadName("Ensouled abyssal head"));
		assertFalse(SupplyTracker.isEnsouledHeadName("Dragon bones"));
		assertFalse(SupplyTracker.isEnsouledHeadName("Shark"));
	}

	@Test
	public void changingDenominationIsNotConsumption()
	{
		// A million coins out, a thousand platinum tokens in. Counted in items that is 999,000
		// gone and the transformation guard can't see it, so the entire balance was billed as
		// supplies — reported after converting a task's alching proceeds at the bank. Counted in
		// gp, which is the only unit the two share, both sides are the same number.
		assertEquals(0L,
			SupplyTracker.familyUnits(ItemID.COINS, -1_000_000, 0, 1)
				+ SupplyTracker.familyUnits(ItemID.PLATINUM, 1000, 0, 1000));

		// And the other way round, which is the same exchange run backwards.
		assertEquals(0L,
			SupplyTracker.familyUnits(ItemID.PLATINUM, -1000, 0, 1000)
				+ SupplyTracker.familyUnits(ItemID.COINS, 1_000_000, 0, 1));
	}

	@Test
	public void coinsGenuinelySpentStillCountAtFaceValue()
	{
		// The fix must not make coins free: only a matched exchange cancels.
		assertEquals(-500L, SupplyTracker.familyUnits(ItemID.COINS, -500, 0, 1));
		assertTrue(SupplyTracker.isCurrency(ItemID.COINS));
		assertTrue(SupplyTracker.isCurrency(ItemID.PLATINUM));
		assertFalse(SupplyTracker.isCurrency(ItemID.SHARK));
	}

	@Test
	public void ordinaryItemsAndDosesKeepTheirOwnUnits()
	{
		assertEquals(-2L, SupplyTracker.familyUnits(ItemID.SHARK, -2, 0, 900));
		// One 4-dose container leaving is four doses, whatever it is priced at.
		assertEquals(-4L, SupplyTracker.familyUnits(ItemID._4DOSEPRAYERRESTORE, -1, 4, 10_000));
	}

	@Test
	public void parsesDoseSuffixes()
	{
		assertEquals(4, SupplyTracker.doseCount("Prayer potion(4)"));
		assertEquals(3, SupplyTracker.doseCount("Prayer potion(3)"));
		assertEquals(1, SupplyTracker.doseCount("Super restore(1)"));
		assertEquals(4, SupplyTracker.doseCount("Saradomin brew(4)"));
		assertEquals(2, SupplyTracker.doseCount("Stamina potion(2)"));
	}

	@Test
	public void ignoresParenthesesThatAreNotDoses()
	{
		// Imbued rings, tablets and clue tiers all end in brackets without being dosed.
		assertEquals(0, SupplyTracker.doseCount("Ring of the gods (i)"));
		assertEquals(0, SupplyTracker.doseCount("Teleport to house (tablet)"));
		assertEquals(0, SupplyTracker.doseCount("Clue scroll (easy)"));
		assertEquals(0, SupplyTracker.doseCount("Prayer cape(t)"));
		assertEquals(0, SupplyTracker.doseCount("Crystal helm (inactive)"));
	}

	@Test
	public void ignoresNamesWithNoSuffix()
	{
		assertEquals(0, SupplyTracker.doseCount("Shark"));
		assertEquals(0, SupplyTracker.doseCount("Vial"));
		assertEquals(0, SupplyTracker.doseCount("Adamant bolts"));
		assertEquals(0, SupplyTracker.doseCount(""));
	}

	@Test
	public void groupsSpentFormsWithTheirChargedItem()
	{
		// Billing the full item price when a charged weapon runs dry would be catastrophic
		// on a Scythe, so these have to land in the same family as their charged form.
		assertEquals("Scythe of vitur", SupplyTracker.stripChargeState("Scythe of vitur (uncharged)"));
		assertEquals("Toxic blowpipe", SupplyTracker.stripChargeState("Toxic blowpipe (empty)"));
		assertEquals("Sanguinesti staff", SupplyTracker.stripChargeState("Sanguinesti staff (uncharged)"));
		assertEquals("Serpentine helm", SupplyTracker.stripChargeState("Serpentine helm (uncharged)"));
		assertEquals("Crystal helm", SupplyTracker.stripChargeState("Crystal helm (inactive)"));
	}

	@Test
	public void groupsDegradationStepsWithTheirIntactItem()
	{
		assertEquals("Dharok's greataxe", SupplyTracker.stripChargeState("Dharok's greataxe 100"));
		assertEquals("Dharok's greataxe", SupplyTracker.stripChargeState("Dharok's greataxe 75"));
		assertEquals("Karil's leathertop", SupplyTracker.stripChargeState("Karil's leathertop 0"));
	}

	@Test
	public void leavesOrdinaryNamesAlone()
	{
		assertEquals("Shark", SupplyTracker.stripChargeState("Shark"));
		assertEquals("Adamant bolts", SupplyTracker.stripChargeState("Adamant bolts"));
		assertEquals("Ring of the gods (i)", SupplyTracker.stripChargeState("Ring of the gods (i)"));
		// A trailing number that isn't a degradation step must not be stripped.
		assertEquals("Team-18 cape", SupplyTracker.stripChargeState("Team-18 cape"));
	}

	@Test
	public void handlesMalformedSuffixes()
	{
		// An empty or unbalanced bracket must not be read as a dose count.
		assertEquals(0, SupplyTracker.doseCount("Weird item()"));
		assertEquals(0, SupplyTracker.doseCount(")"));
		assertEquals(0, SupplyTracker.doseCount("(4)"));
		assertEquals(0, SupplyTracker.doseCount("Mixed(4a)"));
	}

	@Test
	public void explicitDropAbsorbsTheLossItCauses()
	{
		final Map<Integer, SupplyTracker.PendingIgnore> ignores = new HashMap<>();
		ignores.put(100, SupplyTracker.pendingIgnore(5));

		// The drop lands a tick later than the click, so the loss has to be forgiven whenever it
		// turns up — not only in the tick the click happened.
		assertEquals(0, SupplyTracker.applyIgnoredRemoval(ignores, 100, -5));
		assertFalse(ignores.containsKey(100));
	}

	@Test
	public void onlyTheDroppedQuantityIsForgiven()
	{
		final Map<Integer, SupplyTracker.PendingIgnore> ignores = new HashMap<>();
		ignores.put(100, SupplyTracker.pendingIgnore(2));

		// Dropping two and eating three is a cost of one, not a free lunch.
		assertEquals(-1, SupplyTracker.applyIgnoredRemoval(ignores, 100, -3));
		assertFalse(ignores.containsKey(100));

		// A gain is never a drop, and an untracked item is never forgiven.
		assertEquals(4, SupplyTracker.applyIgnoredRemoval(ignores, 100, 4));
		assertEquals(-6, SupplyTracker.applyIgnoredRemoval(ignores, 999, -6));
	}

	@Test
	public void everyFormOfOneItemSharesAFamily()
	{
		// Trident of the seas (full), the partly charged form, and the uncharged form share no
		// stem in their names, so only the variation table can connect them. Recharging or
		// depleting one used to bill the full price of whichever form vanished.
		final String full = SupplyTracker.familyKey(ItemID.TOTS, "Trident of the seas (full)");
		final String charged = SupplyTracker.familyKey(ItemID.TOTS_CHARGED, "Trident of the seas");
		final String uncharged = SupplyTracker.familyKey(ItemID.TOTS_UNCHARGED, "Uncharged trident");

		assertEquals(full, charged);
		assertEquals(charged, uncharged);

		// The swamp variants are their own item, and must not merge into the seas family.
		assertNotEquals(charged,
			SupplyTracker.familyKey(ItemID.TOXIC_TOTS_CHARGED, "Trident of the swamp"));
	}

	@Test
	public void anItemThatRevertsToADifferentItemStaysInOneFamily()
	{
		// A spent abyssal tentacle hands back a kraken tentacle. They are not variations of each
		// other, so without the explicit pairing the tentacle vanishing bills its full price.
		assertEquals(
			SupplyTracker.familyKey(ItemID.ABYSSAL_TENTACLE, "Abyssal tentacle"),
			SupplyTracker.familyKey(ItemID.KRAKEN_TENTACLE, "Kraken tentacle"));

		// The whip is the part actually consumed, and is its own item.
		assertNotEquals(
			SupplyTracker.familyKey(ItemID.ABYSSAL_WHIP, "Abyssal whip"),
			SupplyTracker.familyKey(ItemID.KRAKEN_TENTACLE, "Kraken tentacle"));
	}

	@Test
	public void unrelatedItemsFallBackToTheNameHeuristic()
	{
		// An item outside the variation table keeps the old suffix behaviour.
		assertEquals(
			SupplyTracker.familyKey(-1, "Dharok's greataxe 100"),
			SupplyTracker.familyKey(-2, "Dharok's greataxe 25"));
		assertNotEquals(
			SupplyTracker.familyKey(-1, "Shark"),
			SupplyTracker.familyKey(-2, "Lobster"));
	}
}

package com.slayertaskloot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import net.runelite.api.MenuAction;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

/**
 * What stops a task being billed for everything done after leaving it.
 *
 * <p>Reported from an Araxxor task: the session ran on for the whole idle timeout after the last
 * kill, and the supplies column picked up a Grand Exchange purchase crafted into an amulet of
 * rancour, the noxious point and pommel combined into a halberd (taking the dropped blade out of
 * the drops with them), brimstone keys and a farm run.
 */
public class LeavingTheTaskTest
{
	private static final long MINUTE = 60_000L;

	@Test
	public void onlyAJumpWalkingCannotMakeIsATeleport()
	{
		final WorldPoint start = new WorldPoint(3200, 3200, 0);
		assertFalse(SlayerTaskLootPlugin.isTeleport(start, new WorldPoint(3202, 3201, 0)));
		assertFalse("an agility shortcut",
			SlayerTaskLootPlugin.isTeleport(start, new WorldPoint(3206, 3200, 0)));
		assertFalse("a staircase", SlayerTaskLootPlugin.isTeleport(start, new WorldPoint(3200, 3200, 1)));
		assertTrue(SlayerTaskLootPlugin.isTeleport(start, new WorldPoint(3200, 3200 + 6400, 0)));
		assertTrue(SlayerTaskLootPlugin.isTeleport(start,
			new WorldPoint(3200 + SlayerTaskLootPlugin.TELEPORT_MIN_TILES + 1, 3200, 0)));
		assertFalse("no reading yet", SlayerTaskLootPlugin.isTeleport(null, start));
	}

	@Test
	public void instanceToInstanceIsJudgedByTheTilesTheInstancesWereCopiedFrom()
	{
		// Araxxor's lair and a house can be placed next to each other in instance space.
		final WorldPoint lair = new WorldPoint(7000, 5000, 0);
		final WorldPoint house = new WorldPoint(7004, 5003, 0);
		final WorldPoint lairTemplate = new WorldPoint(3630, 9800, 0);
		final WorldPoint houseTemplate = new WorldPoint(1860, 5700, 0);

		assertTrue("a tablet from the lair to the house",
			SlayerTaskLootPlugin.isTeleport(lair, house, lairTemplate, houseTemplate, true));
		assertFalse("walking between two rooms of the house, which are scattered templates",
			SlayerTaskLootPlugin.isTeleport(house, new WorldPoint(7005, 5003, 0),
				houseTemplate, new WorldPoint(1900, 5760, 0), false));
		assertFalse("crossing a region boundary, which also shows a loading screen",
			SlayerTaskLootPlugin.isTeleport(lairTemplate, new WorldPoint(3631, 9800, 0),
				lairTemplate, new WorldPoint(3631, 9800, 0), true));
	}

	@Test
	public void aKillResumesTheSessionATeleportPausedWithinTheTimeout()
	{
		final long now = 100 * MINUTE;
		assertTrue(SlayerTaskLootPlugin.isResumableTeleportPause("TELEPORT", now - 3 * MINUTE, now, 10));
		assertFalse("past the idle timeout",
			SlayerTaskLootPlugin.isResumableTeleportPause("TELEPORT", now - 11 * MINUTE, now, 10));
		assertFalse("ended rather than paused",
			SlayerTaskLootPlugin.isResumableTeleportPause("IDLE_TIMEOUT", now - MINUTE, now, 10));
		assertFalse(SlayerTaskLootPlugin.isResumableTeleportPause(null, now - MINUTE, now, 10));
	}

	@Test
	public void resumingAPausedSessionAddsASegmentToTheSameSession()
	{
		final TaskLootRecord record = new TaskLootRecord("Araxytes", null, 100, 1L);
		final TaskSession session = record.openNewSession(1_000, false);
		record.closeSession(session.getSessionId(), 2_000, "TELEPORT");
		assertEquals("TELEPORT", session.lastCloseReason());

		record.resumeSession(session.getSessionId(), 3_000, false);

		assertTrue(session.isOpen());
		assertNull(session.lastCloseReason());
		assertEquals(1, record.getTaskSessions().size());
		assertEquals(2, session.getSegments().size());
		assertFalse(session.getSegments().get(1).isOpenedManually());
	}

	@Test
	public void usingAnItemOnSomethingMayBeACraftButCastingASpellIsNot()
	{
		assertTrue(SlayerTaskLootPlugin.isItemCraftAction("Use", MenuAction.WIDGET_TARGET_ON_WIDGET));
		assertTrue(SlayerTaskLootPlugin.isItemCraftAction("Use", MenuAction.WIDGET_TARGET_ON_GAME_OBJECT));
		assertTrue(SlayerTaskLootPlugin.isItemCraftAction("Use", MenuAction.WIDGET_TARGET_ON_NPC));
		assertTrue(SlayerTaskLootPlugin.isItemCraftAction("Combine", MenuAction.CC_OP));
		assertFalse("selecting the item, not using it yet",
			SlayerTaskLootPlugin.isItemCraftAction("Use", MenuAction.WIDGET_TARGET));
		assertFalse("alchemy", SlayerTaskLootPlugin.isItemCraftAction("Cast", MenuAction.WIDGET_TARGET_ON_WIDGET));
		assertFalse(SlayerTaskLootPlugin.isItemCraftAction("Eat", MenuAction.CC_OP));
	}

	@Test
	public void aCraftNeedsSomethingNewToHaveBeenMade()
	{
		assertTrue("a noxious halberd", SupplyTracker.isCraftProduct("Noxious halberd", false, 1));
		assertFalse("alchemy's coins", SupplyTracker.isCraftProduct("#currency", false, 1000));
		assertFalse("potions decanted", SupplyTracker.isCraftProduct("Prayer potion", true, 4));
		assertFalse("a weapon poisoned is the same weapon", SupplyTracker.isCraftProduct("#1215", false, 0));
		assertFalse("something used up", SupplyTracker.isCraftProduct("Noxious point", false, -1));
	}

	@Test
	public void foodAndCoinsStillBillOnACraftingTick()
	{
		assertTrue(SupplyTracker.isCraftInput("Noxious blade", false, -1));
		assertTrue(SupplyTracker.isCraftInput("Amulet of torture", false, -1));
		assertFalse("eaten", SupplyTracker.isCraftInput("wild pie", true, -1));
		assertFalse("spent", SupplyTracker.isCraftInput("#currency", false, -500));
		assertFalse("the product", SupplyTracker.isCraftInput("Noxious halberd", false, 1));
	}
}

package com.slayertaskloot;

import java.util.List;
import javax.annotation.Nullable;
import lombok.Value;

/**
 * Immutable snapshot of a task, resolved on the client thread and handed to the panel.
 *
 * <p>Item names and prices are looked up before crossing to the Swing thread so the panel
 * never touches game state. It only calls {@code ItemManager.getImage}, which is safe off
 * the client thread.
 */
@Value
class TaskView
{
	String assignmentId;
	String taskName;

	@Nullable
	String taskLocation;

	int kills;

	/** The subset of {@link #kills} that could be matched to an observed death, and so to a session. */
	int attributedKills;

	int initialAmount;
	long startedAt;
	long endedAt;
	boolean completed;

	/** GE value of everything credited to the task. */
	long lootValue;

	/** GE value of supplies consumed during the task's sessions. */
	long supplyCost;

	int sessions;
	int onTaskTicks;
	boolean sessionOpen;
	boolean canResumeSession;

	/** Loot rows, highest total value first. */
	List<LootRow> rows;

	/** Consumed supply families, highest cost first. Empty when nothing was used. */
	List<LootRow> supplyRows;

	/** Sessions belonging to this assignment, in creation order. */
	List<SessionView> sessionViews;

	/** Exclusions affecting this task, managed from its Drops section. */
	List<ExcludedDrop> excludedDrops;

	@Value
	static class ExcludedDrop
	{
		String name;
		boolean global;

		@Override
		public String toString()
		{
			return name + (global ? " (all tasks)" : " (this task)");
		}
	}

	@Value
	static class LootRow
	{
		int itemId;
		String name;
		int quantity;
		/** Total GE value of this stack, not the per-item price. */
		long value;
		/**
		 * Unit for {@link #quantity} when it isn't a plain item count — "doses" for
		 * dose-based supply families. Empty otherwise.
		 */
		String unit;

		/**
		 * For a charged item, its components as already-formatted "Blood rune x812" lines,
		 * resolved on the client thread. Empty for an ordinary supply.
		 */
		List<String> breakdown;

		LootRow(int itemId, String name, int quantity, long value, String unit)
		{
			this(itemId, name, quantity, value, unit, java.util.Collections.emptyList());
		}

		LootRow(int itemId, String name, int quantity, long value, String unit,
			List<String> breakdown)
		{
			this.itemId = itemId;
			this.name = name;
			this.quantity = quantity;
			this.value = value;
			this.unit = unit;
			this.breakdown = breakdown;
		}
	}

	@Value
	static class SessionView
	{
		String sessionId;
		int number;
		int onTaskTicks;
		boolean open;

		@Override
		public String toString()
		{
			return "Session " + number + " (" + formatDuration(onTaskTicks) + ")";
		}

		private static String formatDuration(int ticks)
		{
			final long seconds = (long) ticks * 600 / 1000;
			return String.format("%d:%02d", seconds / 60, seconds % 60);
		}
	}
}

package com.slayertaskloot;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/** Parses and updates the user-editable drop exclusion settings. */
final class DropExclusions
{
	private DropExclusions()
	{
	}

	static boolean isExcluded(String global, String perTask, String taskName, String itemName)
	{
		final String item = normalize(itemName);
		if (parseGlobal(global).contains(item))
		{
			return true;
		}

		final TaskGroup group = parseTaskGroups(perTask).get(normalize(taskName));
		return group != null && group.items.containsKey(item);
	}

	static String addGlobal(String value, String itemName)
	{
		final Set<String> entries = displayEntries(value);
		final String wanted = normalize(itemName);
		for (String entry : entries)
		{
			if (normalize(entry).equals(wanted))
			{
				return String.join("; ", entries);
			}
		}
		entries.add(clean(itemName));
		return String.join("; ", entries);
	}

	static String addForTask(String value, String taskName, String itemName)
	{
		final Map<String, TaskGroup> groups = parseTaskGroups(value);
		final String wantedTask = normalize(taskName);
		final TaskGroup group = groups.computeIfAbsent(wantedTask,
			ignored -> new TaskGroup(clean(taskName)));
		group.items.putIfAbsent(normalize(itemName), clean(itemName));
		return formatTaskGroups(groups);
	}

	static String removeGlobal(String value, String itemName)
	{
		final String wanted = normalize(itemName);
		final Set<String> entries = displayEntries(value);
		entries.removeIf(entry -> normalize(entry).equals(wanted));
		return String.join("; ", entries);
	}

	static String removeForTask(String value, String taskName, String itemName)
	{
		final Map<String, TaskGroup> groups = parseTaskGroups(value);
		final String wantedTask = normalize(taskName);
		final TaskGroup group = groups.get(wantedTask);
		if (group != null)
		{
			group.items.remove(normalize(itemName));
			if (group.items.isEmpty())
			{
				groups.remove(wantedTask);
			}
		}
		return formatTaskGroups(groups);
	}

	static List<String> globalEntries(String value)
	{
		return Collections.unmodifiableList(new ArrayList<>(displayEntries(value)));
	}

	static List<String> entriesForTask(String value, String taskName)
	{
		final TaskGroup group = parseTaskGroups(value).get(normalize(taskName));
		return group == null
			? Collections.emptyList()
			: Collections.unmodifiableList(new ArrayList<>(group.items.values()));
	}

	static String formatPerTask(String value)
	{
		return formatTaskGroups(parseTaskGroups(value));
	}

	private static Map<String, TaskGroup> parseTaskGroups(String value)
	{
		final Map<String, TaskGroup> groups = new LinkedHashMap<>();
		for (String entry : split(value))
		{
			final int colon = entry.indexOf(':');
			final int equals = entry.indexOf('=');
			final int delimiter = colon > 0 ? colon : equals;
			if (delimiter <= 0)
			{
				continue;
			}

			final String taskName = clean(entry.substring(0, delimiter));
			final String taskKey = normalize(taskName);
			if (taskKey.isEmpty())
			{
				continue;
			}
			final TaskGroup group = groups.computeIfAbsent(taskKey,
				ignored -> new TaskGroup(taskName));
			// The new Task: Item, Item form groups items with commas. The legacy
			// Task = Item form treats everything after '=' as one item for compatibility.
			final String[] items = colon > 0
				? entry.substring(delimiter + 1).split(",")
				: new String[]{entry.substring(delimiter + 1)};
			for (String item : items)
			{
				final String itemName = clean(item);
				if (!itemName.isEmpty())
				{
					group.items.putIfAbsent(normalize(itemName), itemName);
				}
			}
		}
		return groups;
	}

	private static String formatTaskGroups(Map<String, TaskGroup> groups)
	{
		final List<String> entries = new ArrayList<>();
		for (TaskGroup group : groups.values())
		{
			if (!group.items.isEmpty())
			{
				entries.add(group.name + ": " + String.join(", ", group.items.values()));
			}
		}
		return String.join("; ", entries);
	}

	private static Set<String> parseGlobal(String value)
	{
		final Set<String> entries = new LinkedHashSet<>();
		for (String entry : split(value))
		{
			entries.add(normalize(entry));
		}
		return entries;
	}

	private static Set<String> displayEntries(String value)
	{
		final Set<String> entries = new LinkedHashSet<>();
		for (String entry : split(value))
		{
			entries.add(clean(entry));
		}
		return entries;
	}

	private static String[] split(String value)
	{
		return value == null || value.trim().isEmpty()
			? new String[0]
			: value.split("[;\\r\\n]+");
	}

	private static String clean(String value)
	{
		return value == null ? "" : value.trim().replaceAll("\\s+", " ");
	}

	private static String normalize(String value)
	{
		return clean(value).toLowerCase(Locale.ROOT);
	}

	private static final class TaskGroup
	{
		private final String name;
		private final Map<String, String> items = new LinkedHashMap<>();

		private TaskGroup(String name)
		{
			this.name = name;
		}
	}
}

