package com.slayertaskloot;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.http.api.item.ItemPrice;

/**
 * Values supplies consumed by diffing everything the player is carrying.
 *
 * <p>Rather than matching consumption against a hardcoded table of food, potion, rune and
 * ammunition ids — which needs revisiting every time an item is added to the game — this
 * snapshots what the player carries and charges the loss in GE value between snapshots.
 * One rule covers food, potions, runes, ammunition, cannonballs and teleports at once,
 * and keeps working for items that don't exist yet.
 *
 * <p>Losses are totalled per <em>item family</em> rather than across the whole diff. That
 * matters for accuracy as much as for the breakdown: netting everything together would let
 * a drop picked up on the same tick as a potion sip cancel that sip out, silently losing
 * the cost. Judged per family, the drop's gain and the potion's loss don't meet.
 *
 * <p>A family is a base item name with its dose variants folded in, so a 4-dose leaving and
	 * a 3-dose arriving is recognised as a single dose used. Drinkable families are priced from
	 * the full 4-dose container (or 2-dose mix), carrying fractional-GP remainders between uses.
 *
 * <p>Inventory, worn equipment and the rune pouch are diffed <em>jointly</em>, because
 * items move between them. Diffing containers separately would read wielding a stack of
 * bolts as consuming the whole stack, and casting from a rune pouch would be invisible
 * entirely (pouch contents live in varbits, not in an item container).
 *
	 * <p>Selected item charges are added as synthetic resource quantities from RuneLite varbits.
	 * Items with no GE price — most untradeables, including crystal equipment — value at zero.
	 * They're still listed at zero gp when consumed, so that a supply which is tracked but free
	 * doesn't look identical to one that isn't tracked at all.
 */
@Slf4j
class SupplyTracker
{
	/**
	 * Equipment deployed into the world rather than used up. A cannon's four parts leave the
	 * inventory on setup and come back on pickup, so diffing them reads building a cannon as
	 * ~450k of supplies spent and dismantling it as loot found. Neither happened, so they stay
	 * out of the snapshot entirely and no diff can ever see them move.
	 */
	private static final Set<Integer> DEPLOYABLE_ITEMS = new HashSet<>(Arrays.asList(
		ItemID.TWPART1, ItemID.TWPART2, ItemID.TWPART3, ItemID.TWPART4,
		ItemID.LEAGUE_3_MULTICANNON_BASE, ItemID.LEAGUE_3_MULTICANNON_STAND,
		ItemID.LEAGUE_3_MULTICANNON_BARRELS, ItemID.LEAGUE_3_MULTICANNON_FURNACE));


	/**
	 * Items that become a <em>different</em> item when spent, which the variation table has no
	 * reason to connect because they aren't variations of each other.
	 *
	 * <p>An abyssal tentacle reverts to a kraken tentacle: the whip inside it is what was consumed,
	 * and the tentacle is handed back. Left ungrouped, the abyssal tentacle disappearing reads as
	 * its whole GE price being used up in one tick. Mapped onto the form it becomes, the pair nets
	 * to zero items and the transformation guard skips it — the whip having already been billed
	 * per attack over the preceding 10,000 hits.
	 *
	 * <p>Includes the destination mapped to itself, so both sides of the change agree on a key.
	 */
	private static final Map<Integer, Integer> SPENT_FORMS = new HashMap<>();

	static
	{
		SPENT_FORMS.put(ItemID.ABYSSAL_TENTACLE, ItemID.KRAKEN_TENTACLE);
		SPENT_FORMS.put(ItemID.KRAKEN_TENTACLE, ItemID.KRAKEN_TENTACLE);
	}

	/**
	 * Coins and platinum tokens, which are the same wealth in two denominations.
	 *
	 * <p>Held as one family and measured in <em>gp</em> rather than in items, because they are the
	 * one pair the client prices exactly — {@code ItemManager} hardcodes 1 gp a coin and 1000 gp a
	 * token — and the one pair whose item counts are not commensurable at all. Exchanging a million
	 * coins for a thousand tokens is a thousand items arriving against a million leaving; in items
	 * that is an enormous loss and the transformation guard can't see it, so the whole balance was
	 * billed as supplies. It was reported that way: alching through a task tracked correctly, then
	 * converting the proceeds at the bank subtracted every coin of them from the profit.
	 *
	 * <p>Measured in gp both sides of the exchange are the same number and the family nets to zero,
	 * so no charge can be built out of a denomination change however it is done — banker, interface
	 * or otherwise. Coins genuinely spent still bill, at exactly their face value.
	 */
	private static final Set<Integer> CURRENCY_ITEMS = new HashSet<>(Arrays.asList(
		ItemID.COINS, ItemID.COINS_2, ItemID.COINS_3, ItemID.COINS_4, ItemID.COINS_5,
		ItemID.COINS_25, ItemID.COINS_100, ItemID.COINS_250, ItemID.COINS_1000,
		ItemID.COINS_10000, ItemID.PLATINUM));

	private static final String CURRENCY_FAMILY = "#currency";

	/**
	 * Ticks an unmatched drop stays outstanding. Long enough for the container update to land,
	 * short enough that it can't swallow a real use of the same item later in the trip.
	 */
	private static final int IGNORE_EXPIRY_TICKS = 3;

	/**
	 * Ticks a craft attempt stays live, long enough to get through a confirmation dialog. Renewed
	 * by every crafted item, so a Make-All keeps it open for as long as it runs.
	 */
	private static final int CRAFT_WINDOW_TICKS = 10;

	/** Rune pouch slots. Contents live in varbits rather than an item container. */
	private static final int[] RUNE_POUCH_TYPE_VARBITS = {
		VarbitID.RUNE_POUCH_TYPE_1,
		VarbitID.RUNE_POUCH_TYPE_2,
		VarbitID.RUNE_POUCH_TYPE_3,
		VarbitID.RUNE_POUCH_TYPE_4,
		VarbitID.RUNE_POUCH_TYPE_5,
		VarbitID.RUNE_POUCH_TYPE_6,
	};

	private static final int[] RUNE_POUCH_QUANTITY_VARBITS = {
		VarbitID.RUNE_POUCH_QUANTITY_1,
		VarbitID.RUNE_POUCH_QUANTITY_2,
		VarbitID.RUNE_POUCH_QUANTITY_3,
		VarbitID.RUNE_POUCH_QUANTITY_4,
		VarbitID.RUNE_POUCH_QUANTITY_5,
		VarbitID.RUNE_POUCH_QUANTITY_6,
	};

	private final Client client;
	private final ItemManager itemManager;
	private final Map<String, DosePrice> dosePrices = new HashMap<>();
	private final Map<String, Long> doseRemainders = new HashMap<>();

	/** Explicit drops awaiting the container update that carries them out. */
	private final Map<Integer, PendingIgnore> pendingIgnores = new HashMap<>();

	/** What the last {@link #charge()} saw arrive, as itemId -> quantity gained. */
	private final Map<Integer, Integer> lastGains = new HashMap<>();

	/** Ticks left on the latest craft attempt. See {@link #noteCraftAttempt()}. */
	private int craftTicksLeft;
	private boolean eyeUsesTears = true;

	/** Whether burying or scattering prayer remains counts as a supply. See the config item. */
	private boolean chargePrayerRemains;

	/**
	 * Ammunition currently in the cannon's magazine. Only the load message says which of the
	 * two kinds it is; the count itself is a plain varp.
	 */
	private int loadedCannonballId = ItemID.MCANNONBALL;

	/** itemId -> quantity across inventory, worn equipment and rune pouch. Null until baselined. */
	private Map<Integer, Integer> snapshot;

	@Inject
	SupplyTracker(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	/** Drop the baseline entirely. The next {@link #charge()} re-baselines and charges nothing. */
	void clear()
	{
		snapshot = null;
		pendingIgnores.clear();
		lastGains.clear();
		craftTicksLeft = 0;
	}

	/**
	 * The player just did something that may make one item out of others — used an item on another
	 * item, an object or an NPC, or picked a combining option.
	 *
	 * <p>Making something isn't consumption: the inputs haven't been used up, they've become the
	 * thing that arrived. Billed, they posted the full price of whatever went in — an amulet of
	 * torture and an etched fang crafted into an amulet of rancour charged the task over 47M, and a
	 * noxious blade combined into a halberd was billed and then netted out of the task's drops.
	 *
	 * <p>Nothing is forgiven on the click alone. It takes a tick inside the window on which a
	 * <em>new</em> item arrives — a family gaining items — for its losses to read as a craft. That
	 * is what keeps the click from excusing real consumption: poisoning a weapon, drinking to an
	 * empty vial and eating down to a pie dish all use an item up without anything new appearing
	 * from the ingredients, or appear only as the same item in another form.
	 */
	void noteCraftAttempt()
	{
		craftTicksLeft = CRAFT_WINDOW_TICKS;
	}

	/**
	 * Whether bones and ashes count as supplies when they are used up.
	 *
	 * <p>Deliberately not a resync. Nothing in the snapshot depends on the answer — only what the
	 * diff is allowed to build a row out of — so re-baselining here would throw away whatever the
	 * current tick had already consumed for no gain.
	 */
	boolean isChargingPrayerRemains()
	{
		return chargePrayerRemains;
	}

	void setChargePrayerRemains(boolean chargePrayerRemains)
	{
		this.chargePrayerRemains = chargePrayerRemains;
	}

	/**
	 * What the last {@link #charge()} saw arrive, as itemId -> quantity.
	 *
	 * <p>Only bones and ashes ask, and only to tell "a bonecrusher consumed these where they fell"
	 * apart from "the player picked them up and may bury them later" — the second is charged by the
	 * ordinary diff when it happens, so charging it again from the drop would bill it twice.
	 */
	Map<Integer, Integer> gainsThisTick()
	{
		return Collections.unmodifiableMap(lastGains);
	}

	/**
	 * Switches which resource an eye of ayak is billed against, re-baselining so the swap
	 * between two different synthetic quantities isn't itself read as consumption. Silent when
	 * the answer hasn't changed — this is re-applied on every config change, and a resync there
	 * would throw away whatever that tick had used.
	 */
	boolean isEyeUsingTears()
	{
		return eyeUsesTears;
	}

	void setEyeUsesTears(boolean eyeUsesTears)
	{
		if (this.eyeUsesTears == eyeUsesTears)
		{
			return;
		}
		this.eyeUsesTears = eyeUsesTears;
		resync();
	}

	/**
	 * Records which ammunition the cannon is loaded with. Deliberately doesn't re-baseline:
	 * the type can only change across an unload, which empties the magazine first, so the
	 * ammunition counted under the old id has already returned to the inventory.
	 */
	void setLoadedCannonballId(int itemId)
	{
		if (itemId > 0)
		{
			loadedCannonballId = itemId;
		}
	}



	/**
	 * Re-baseline without charging. Used when a container change can't be read as
	 * consumption — banking, trading, shops, the GE, dying, or an explicit drop.
	 */
	void resync()
	{
		snapshot = takeSnapshot();
		// The new baseline already reflects whatever happened, so nothing is left to forgive.
		pendingIgnores.clear();
		if (craftTicksLeft > 0)
		{
			craftTicksLeft--;
		}
	}

	/**
	 * Marks an explicitly dropped stack as not consumption, to be honoured whenever the removal
	 * actually shows up.
	 *
	 * <p>A menu click arrives before the container update that carries it out, and how many ticks
	 * later that update lands isn't ours to decide. Adjusting the baseline on the spot only worked
	 * if the removal landed within the same tick's diff: if it landed later, the next diff
	 * overwrote the baseline with a snapshot that still held the item, and the removal after that
	 * was charged as consumption. That is why dropping an untradeable posted it as a 0 gp supply.
	 *
	 * <p>Held as an intention instead, and matched against the loss whenever it appears. Intentions
	 * expire so that a drop can't quietly absorb a genuine use of the same item minutes later.
	 */
	void ignoreRemoval(int itemId, int quantity)
	{
		if (itemId <= 0 || quantity <= 0)
		{
			return;
		}
		final PendingIgnore pending = pendingIgnores.computeIfAbsent(
			itemManager.canonicalize(itemId), k -> new PendingIgnore());
		pending.quantity += quantity;
		pending.ticksLeft = IGNORE_EXPIRY_TICKS;
	}

	/**
	 * Cancels a loss against an outstanding intention to drop that item.
	 *
	 * @return the delta with any ignored quantity absorbed, leaving 0 when the whole loss was the
	 * drop the player asked for
	 */
	static int applyIgnoredRemoval(Map<Integer, PendingIgnore> ignores, int itemId, int delta)
	{
		if (delta >= 0)
		{
			return delta;
		}
		final PendingIgnore pending = ignores.get(itemId);
		if (pending == null)
		{
			return delta;
		}

		final int absorbed = Math.min(pending.quantity, -delta);
		pending.quantity -= absorbed;
		if (pending.quantity <= 0)
		{
			ignores.remove(itemId);
		}
		return delta + absorbed;
	}

	private void expireIgnoredRemovals()
	{
		pendingIgnores.values().removeIf(pending -> --pending.ticksLeft <= 0);
	}

	/** An explicit drop waiting for the container update that performs it. */
	static final class PendingIgnore
	{
		private int quantity;
		private int ticksLeft;
	}

	/** Test seam: an outstanding drop of {@code quantity}, fresh enough not to have expired. */
	static PendingIgnore pendingIgnore(int quantity)
	{
		final PendingIgnore pending = new PendingIgnore();
		pending.quantity = quantity;
		pending.ticksLeft = IGNORE_EXPIRY_TICKS;
		return pending;
	}

	/**
	 * Diffs the carried snapshot and reports what was consumed since the previous call.
	 *
	 * <p>Accounting is per item family, not across the whole diff. Only families that lost
	 * value are charged, so a drop picked up on the same tick as a potion sip can no longer
	 * cancel that sip out — each is judged on its own.
	 *
	 * @return the cost and its breakdown, or {@link SupplyCharge#EMPTY} when nothing was
	 * consumed or there was no baseline to compare against
	 */
	SupplyCharge charge()
	{
		final Map<Integer, Integer> current = takeSnapshot();

		if (snapshot == null)
		{
			snapshot = current;
			return SupplyCharge.EMPTY;
		}

		final Set<Integer> ids = new HashSet<>(snapshot.keySet());
		ids.addAll(current.keySet());

		// Grouped by base name so dose variants of one potion are accounted for together.
		final Map<String, Family> families = new LinkedHashMap<>();
		lastGains.clear();

		for (Integer id : ids)
		{
			final int delta = applyIgnoredRemoval(
				pendingIgnores, id, current.getOrDefault(id, 0) - snapshot.getOrDefault(id, 0));
			if (delta == 0)
			{
				continue;
			}
			if (delta > 0)
			{
				lastGains.merge(id, delta, Integer::sum);
			}
			if (delta < 0 && isLootOnlyItem(id))
			{
				// Prayer remains and ensouled heads are loot rather than task supplies.
				// Never let their removal create a row which netting cancels against loot.
				continue;
			}

			final String name = itemName(id);
			final boolean currency = isCurrency(id);
			final int doses = currency ? 0 : unitsFor(id, name);
			final long unitPrice = itemManager.getItemPrice(id);
			final String doseBase = doses > 0 ? doseBaseName(name) : null;
			final String base = currency
				? CURRENCY_FAMILY
				: doseBase != null
					? doseBase
					: familyKey(id, name);

			final Family family = families.computeIfAbsent(base, k -> new Family());
			family.value += (long) delta * unitPrice;
			family.units += familyUnits(id, delta, doses, unitPrice);

			if (doseBase != null)
			{
				family.doseBased = true;
				// Portions are priced off the whole food rather than off a dose container, so
				// the two resolve their unit price differently. See resolvePortionPrice().
				family.portionFood = doseCount(name) <= 0;
			}
			// Represent the family by what was consumed, not what replaced it, so a row reads
			// "Prayer potion" and not the 3-dose it turned into.
			if (delta < 0 && doses >= family.bestDose)
			{
				family.bestDose = doses;
				family.representativeId = id;
			}
		}

		final Map<Integer, Integer> snapshotBefore = snapshot;
		snapshot = current;

		final boolean crafted = craftTicksLeft > 0 && hasCraftedProduct(families);
		if (crafted)
		{
			// Keep the window open for the next item of a Make-All.
			craftTicksLeft = CRAFT_WINDOW_TICKS;
		}

		long total = 0;
		final List<SupplyCharge.Row> rows = new ArrayList<>();

		for (Map.Entry<String, Family> entry : families.entrySet())
		{
			final String base = entry.getKey();
			final Family family = entry.getValue();

			if (crafted && isCraftInput(base, family))
			{
				log.debug("not charging {} x{}: went into something crafted this tick",
					itemName(family.representativeId), -family.units);
				continue;
			}

			// One item out, one item in: a transformation, not consumption. A trident running dry
			// or being recharged, barrows gear degrading a step, a scythe emptying — the item count
			// is unchanged and nothing was used up, but the two forms can differ by the item's
			// entire GE price, because the charged form of most of them is untradeable and prices
			// at zero. Billing that difference posted the full cost of an uncharged trident for
			// recharging one. The runes and coins that did the recharging are still charged; they
			// really did leave the inventory.
			if (!family.doseBased && family.units == 0)
			{
				continue;
			}
			// A family that lost units but no value is an untradeable being consumed: ecto-tokens
			// off a bonecrusher, say. Reported as a zero-gp row rather than dropped, so that
			// "tracked, but genuinely free" is distinguishable from "not tracked at all" — the
			// silence was indistinguishable from a bug, and got reported as one.
			final boolean unpricedConsumption = family.value == 0 && family.units < 0;
			if (family.value >= 0
				&& !(family.doseBased && family.units < 0)
				&& !unpricedConsumption)
			{
				// Gained value — loot, or a potion topped up. Not a cost.
				continue;
			}

			long cost = -family.value;
			if (family.doseBased && family.units < 0 && isConsumable(family.representativeId))
			{
				final DosePrice dosePrice = family.portionFood
					? resolvePortionPrice(base)
					: resolveDosePrice(base);
				if (dosePrice != null)
				{
					final long numerator = (long) -family.units * dosePrice.fullPrice
						+ doseRemainders.getOrDefault(base, 0L);
					cost = numerator / dosePrice.doses;
					doseRemainders.put(base, numerator % dosePrice.doses);
					family.representativeId = dosePrice.itemId;
				}
				else
				{
					family.doseBased = false;
				}
			}
			else if (family.doseBased)
			{
				// Teleport jewellery and other charged items also use numeric suffixes. Only an
				// item the player drinks or eats may use dose normalization.
				family.doseBased = false;
			}
			total += cost;

			if (family.units < 0)
			{
				rows.add(new SupplyCharge.Row(
					family.representativeId,
					(int) -family.units,
					cost,
					family.doseBased));
			}
		}

		expireIgnoredRemovals();
		if (craftTicksLeft > 0)
		{
			craftTicksLeft--;
		}
		if (!rows.isEmpty() && log.isDebugEnabled())
		{
			// Every charge, with the raw per-id deltas behind it. A charge that shouldn't have
			// happened is otherwise indistinguishable from one that should: the panel shows the
			// same row either way, and netting hides it entirely once loot cancels it out.
			// Printing what the diff actually saw is what settled the CHARGES_* block, and it's
			// the only way to tell "the pouch wasn't in the snapshot this tick" apart from
			// "these runes really were spent".
			for (SupplyCharge.Row row : rows)
			{
				log.debug("charged {} x{} for {} gp", itemName(row.getItemId()), row.getQuantity(),
					row.getValue());
			}
			for (Integer id : ids)
			{
				final int before = snapshotBefore.getOrDefault(id, 0);
				final int after = current.getOrDefault(id, 0);
				if (before != after)
				{
					log.debug("  diff {} ({}) {} -> {}", itemName(id), id, before, after);
				}
			}
			logRunePouch();
		}
		return total <= 0 && rows.isEmpty() ? SupplyCharge.EMPTY : new SupplyCharge(total, rows);
	}

	/**
	 * A whole-item consumption the carried diff can never see, because the item was used up before
	 * it reached the player: a bonecrusher's bones, an ash sanctifier's ashes.
	 *
	 * <p>Priced and shaped exactly like the row the diff would have produced had the player buried
	 * them by hand, so netting cancels it against the drop it came from either way.
	 */
	SupplyCharge consumedItem(int itemId, int quantity)
	{
		if (itemId <= 0 || quantity <= 0)
		{
			return SupplyCharge.EMPTY;
		}
		final long value = (long) itemManager.getItemPrice(itemId) * quantity;
		return new SupplyCharge(value, Collections.singletonList(
			new SupplyCharge.Row(itemId, quantity, value, false)));
	}

	SupplyCharge componentCharge(int... itemIdQuantityPairs)
	{
		long total = 0;
		final List<SupplyCharge.Row> rows = new ArrayList<>();
		for (int i = 0; i + 1 < itemIdQuantityPairs.length; i += 2)
		{
			final int itemId = itemIdQuantityPairs[i];
			final int quantity = itemIdQuantityPairs[i + 1];
			if (quantity <= 0)
			{
				continue;
			}
			final long value = (long) itemManager.getItemPrice(itemId) * quantity;
			total += value;
			rows.add(new SupplyCharge.Row(itemId, quantity, value, false));
		}
		return total == 0 ? SupplyCharge.EMPTY : new SupplyCharge(total, rows);
	}

	/**
	 * One use of a charged item, billed as a single row named after the item with its components
	 * behind it.
	 *
	 * @param chargedItemId the item being used up, which the row is named after
	 * @param extraValue    cost that isn't a whole component, such as a fraction of a vial
	 * @param itemIdQuantityPairs component item ids and how many whole ones a use consumes
	 */
	SupplyCharge chargedItemUse(int chargedItemId, long extraValue, int... itemIdQuantityPairs)
	{
		return chargedItemUse(chargedItemId, extraValue, Collections.emptyMap(), itemIdQuantityPairs);
	}

	/**
	 * As {@link #chargedItemUse(int, long, int...)}, for a use that also spends a <em>fraction</em>
	 * of a component.
	 *
	 * @param fractionHundredths component ids to hundredths of an item, whose cost the caller has
	 *                           already smoothed into {@code extraValue}. Listed in the breakdown
	 *                           but not priced again here, so the row still sums to its total
	 */
	SupplyCharge chargedItemUse(int chargedItemId, long extraValue,
		Map<Integer, Integer> fractionHundredths, int... itemIdQuantityPairs)
	{
		long total = extraValue;
		final Map<Integer, Integer> components = new LinkedHashMap<>();
		for (int i = 0; i + 1 < itemIdQuantityPairs.length; i += 2)
		{
			final int itemId = itemIdQuantityPairs[i];
			final int quantity = itemIdQuantityPairs[i + 1];
			if (quantity <= 0)
			{
				continue;
			}
			total += (long) itemManager.getItemPrice(itemId) * quantity;
			components.merge(itemId, quantity * SupplyCharge.COMPONENT_SCALE, Integer::sum);
		}
		fractionHundredths.forEach((itemId, hundredths) ->
		{
			if (hundredths > 0)
			{
				components.merge(itemId, hundredths, Integer::sum);
			}
		});

		if (chargedItemId <= 0)
		{
			return SupplyCharge.EMPTY;
		}
		return new SupplyCharge(total, Collections.singletonList(
			new SupplyCharge.Row(chargedItemId, 1, total, false, components)));
	}

	private static boolean hasCraftedProduct(Map<String, Family> families)
	{
		for (Map.Entry<String, Family> entry : families.entrySet())
		{
			final Family family = entry.getValue();
			if (isCraftProduct(entry.getKey(), family.doseBased, family.units))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean isCraftInput(String base, Family family)
	{
		return isCraftInput(base, family.doseBased, family.units);
	}

	/**
	 * Whether a family's movement is something new having been made: more of it than before.
	 *
	 * <p>Coins are left out because alchemy produces them, and alchemy is billed through its own
	 * path. Dose families are left out because a potion's doses reshuffle between containers
	 * without anything being made. A family whose count didn't change — a weapon going from plain
	 * to poisoned, a trident being charged — is the same item in another form, not a product.
	 */
	static boolean isCraftProduct(String base, boolean doseBased, long units)
	{
		return units > 0 && !doseBased && !CURRENCY_FAMILY.equals(base);
	}

	/**
	 * Whether a family that lost items on a crafting tick went into the product rather than being
	 * used. Food and potions still bill, since eating mid-craft is still eating, and so do coins.
	 */
	static boolean isCraftInput(String base, boolean doseBased, long units)
	{
		return units < 0 && !doseBased && !CURRENCY_FAMILY.equals(base);
	}

	/** Whether an item is coins or platinum tokens. See {@link #CURRENCY_ITEMS}. */
	static boolean isCurrency(int itemId)
	{
		return CURRENCY_ITEMS.contains(itemId);
	}

	/**
	 * What one item's movement contributes to its family's unit count, in whatever unit that
	 * family is commensurable in.
	 *
	 * <p>Three units, and each exists because the one below it gets a real case wrong. Ordinary
	 * items count in items. Dose variants count in <em>doses</em>, so a 4-dose leaving and a 3-dose
	 * arriving is one dose used rather than two items changing hands. Coins and platinum tokens
	 * count in <em>gp</em>, so exchanging a million coins for a thousand tokens is the same number
	 * both ways instead of a 999,000-item loss — which is what got the whole balance billed as
	 * supplies when a task's alching proceeds were converted at the bank.
	 *
	 * <p>The unit only has to make the two sides of a transformation cancel; the value column is
	 * computed separately and is unaffected by the choice.
	 */
	static long familyUnits(int itemId, int delta, int doses, long unitPrice)
	{
		return isCurrency(itemId)
			? (long) delta * unitPrice
			: (long) delta * Math.max(doses, 1);
	}

	/**
	 * Resolves a portion family to the whole food it is eaten out of, priced per portion.
	 *
	 * <p>Kept apart from {@link #resolveDosePrice(String)} rather than folded into it. That method
	 * accepts only a (4) or a (2) because a potion's other containers are worth less per dose than
	 * the full one, and widening it to whatever container it happened to see first would re-price
	 * every potion in the game off a (3). A whole food has exactly one container, so there is
	 * nothing to choose between here — only the whole itself will do.
	 */
	private DosePrice resolvePortionPrice(String base)
	{
		if (dosePrices.containsKey(base))
		{
			return dosePrices.get(base);
		}

		for (ItemPrice candidate : itemManager.search(base))
		{
			final String name = candidate.getName();
			if (name == null || !base.equalsIgnoreCase(name))
			{
				continue;
			}
			final int portions = portionCount(name);
			final long price = itemManager.getItemPrice(candidate.getId());
			if (portions > 1 && price > 0)
			{
				final DosePrice whole = new DosePrice(candidate.getId(), portions, price);
				dosePrices.put(base, whole);
				return whole;
			}
		}
		return null;
	}

	/** Resolves a dose family to its tradeable full container: (4), or (2) for mixes. */
	private DosePrice resolveDosePrice(String base)
	{
		if (dosePrices.containsKey(base))
		{
			return dosePrices.get(base);
		}

		DosePrice best = null;
		for (ItemPrice candidate : itemManager.search(base))
		{
			final String name = candidate.getName();
			if (name == null)
			{
				continue;
			}
			// Matched on the parsed base and dose rather than by rebuilding the name, because the
			// game is not consistent about the space before the dose: "Prayer potion(4)" but
			// "Serum 207 (4)" and "Overload (4)". Concatenating base + "(4)" missed those two
			// families outright, which silently dropped them out of dose netting altogether.
			if (!base.equalsIgnoreCase(doseBaseName(name)))
			{
				continue;
			}
			final int doses = doseCount(name);
			if (doses == 4)
			{
				best = new DosePrice(candidate.getId(), 4, itemManager.getItemPrice(candidate.getId()));
				break;
			}
			if (doses == 2)
			{
				best = new DosePrice(candidate.getId(), 2, itemManager.getItemPrice(candidate.getId()));
			}
		}

		if (best != null && best.fullPrice > 0)
		{
			dosePrices.put(base, best);
			return best;
		}
		return null;
	}

	private String itemName(int itemId)
	{
		try
		{
			final ItemComposition comp = itemManager.getItemComposition(itemId);
			if (comp != null && comp.getName() != null && !comp.getName().isEmpty())
			{
				return comp.getName();
			}
		}
		catch (Exception ex)
		{
			// Fall through — an unresolvable name just means this id is its own family.
		}
		return "Item #" + itemId;
	}

	/** Whether the player drinks or eats this item, which is what dose and portion pricing is for. */
	private boolean isConsumable(int itemId)
	{
		return hasAction(itemId, "Drink") || hasAction(itemId, "Eat");
	}

	private boolean isEdible(int itemId)
	{
		return hasAction(itemId, "Eat");
	}

	private boolean hasAction(int itemId, String wanted)
	{
		try
		{
			final ItemComposition comp = itemManager.getItemComposition(itemId);
			if (comp != null && comp.getInventoryActions() != null)
			{
				for (String action : comp.getInventoryActions())
				{
					if (wanted.equalsIgnoreCase(action))
					{
						return true;
					}
				}
			}
		}
		catch (Exception ex)
		{
			// Fall back to the observed variant-value delta if composition data is unavailable.
		}
		return false;
	}

	/**
	 * How many units of its family this item holds — doses for a "(n)" container, portions for food
	 * eaten in more than one bite, and 0 for anything counted in whole items.
	 *
	 * <p>The portion half is asked of the item rather than of its name alone, because the pie
	 * family holds the uncooked and burnt forms as well and neither is eaten in halves. Counting
	 * those in portions would report one uncooked pie as a supply of two.
	 */
	private int unitsFor(int itemId, String name)
	{
		final int doses = doseCount(name);
		if (doses > 0)
		{
			return doses;
		}
		final int portions = portionCount(name);
		return portions > 0 && isEdible(itemId) ? portions : 0;
	}

	boolean isLootOnlyItem(int itemId)
	{
		try
		{
			final ItemComposition comp = itemManager.getItemComposition(itemId);
			if (comp == null)
			{
				return false;
			}
			// An ensouled head is spent on a reanimation for the experience, and is loot however
			// this is set. Only bones and ashes are in question.
			if (isEnsouledHeadName(comp.getName()) || isSpentLootName(comp.getName()))
			{
				return true;
			}
			return !chargePrayerRemains && isPrayerRemains(comp);
		}
		catch (Exception ex)
		{
			return false;
		}
	}

	/** Whether an item is bones or ashes, irrespective of whether they are being charged. */
	boolean isPrayerRemains(int itemId)
	{
		try
		{
			return isPrayerRemains(itemManager.getItemComposition(itemId));
		}
		catch (Exception ex)
		{
			return false;
		}
	}

	private static boolean isPrayerRemains(ItemComposition comp)
	{
		return comp != null && (hasPrayerRemainsAction(comp.getInventoryActions())
			|| isPrayerRemainsName(comp.getName()));
	}

	/** Testable classification shared by every kind of bone and demonic ash. */
	static boolean hasPrayerRemainsAction(String[] actions)
	{
		if (actions == null)
		{
			return false;
		}
		for (String action : actions)
		{
			if ("Bury".equalsIgnoreCase(action) || "Scatter".equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}

	static boolean isLootOnlyName(String name)
	{
		return isPrayerRemainsName(name) || isEnsouledHeadName(name) || isSpentLootName(name);
	}

	/**
	 * Untradeable loot that is spent rather than bought: a tarnished item polished into the weapon
	 * or jewellery it becomes, and a venator heart sacrificed at an Aranei shrine. Both arrive as
	 * drops of the task that is billing them, and neither was ever a supply.
	 *
	 * <p>Billed, they take the unpriced-consumption branch and post a 0 gp row, netting cancels
	 * that against the drop, and both sides reach zero and are deleted — so a tarnished spear
	 * polished into a rune spear left no trace in either column. The row was the visible half; the
	 * invisible half is that the drop it cancelled was the only record the task had of it.
	 *
	 * <p>Matched by name rather than by any property of the item. "Untradeable and unpriced" would
	 * be the general rule and it is too wide: it would quietly stop billing genuine supplies that
	 * happen to price at zero, which is the failure this codebase keeps meeting from the other
	 * direction. An explicit set undercounts a name nobody has added yet, which is a row that reads
	 * 0 gp rather than a cost that silently disappears.
	 */
	static boolean isSpentLootName(String name)
	{
		if (name == null)
		{
			return false;
		}
		final String lower = name.toLowerCase(java.util.Locale.ROOT);
		return lower.startsWith("tarnished ") || lower.equals("venator heart");
	}

	static boolean isPrayerRemainsName(String name)
	{
		if (name == null)
		{
			return false;
		}
		final String lower = name.toLowerCase(java.util.Locale.ROOT);
		return lower.endsWith(" ashes") || lower.endsWith(" bones");
	}

	static boolean isEnsouledHeadName(String name)
	{
		if (name == null)
		{
			return false;
		}
		final String lower = name.toLowerCase(java.util.Locale.ROOT);
		return lower.startsWith("ensouled ") && lower.endsWith(" head");
	}

	Map<Integer, Integer> takeRunePouchSnapshot()
	{
		final Map<Integer, Integer> snapshot = new HashMap<>();
		addRunePouch(snapshot);
		return snapshot;
	}

	/**
	 * An item name reduced to the family it is counted in: a potion without its "(n)", or the whole
	 * food a portion came out of. Null when the item is counted in whole items.
	 *
	 * <p>Trimmed, because the space before the dose is present in some names and not others.
	 */
	static String doseBaseName(String name)
	{
		if (name == null)
		{
			return null;
		}
		if (doseCount(name) <= 0)
		{
			return portionBaseName(name);
		}
		final int open = name.lastIndexOf('(');
		return open <= 0 ? null : name.substring(0, open).trim();
	}

	/**
	 * How many units of its family this item name holds, counting doses and food portions alike.
	 *
	 * <p>The pairing of {@link #doseBaseName(String)} — what netting needs to put a supply row and
	 * the drop that paid for it into the same units.
	 */
	static int unitsPerItem(String name)
	{
		final int doses = doseCount(name);
		return doses > 0 ? doses : portionCount(name);
	}

	/** Parts of a whole food whose name shares no stem with the whole they came out of. */
	private static final Map<String, String> NAMED_FOOD_PARTS = new HashMap<>();

	/** How a part of a whole food is named, and how many portions that part holds. */
	private static final Map<String, Integer> FOOD_PART_PREFIXES = new LinkedHashMap<>();

	/** Whole foods eaten in three, which nothing in their names gives away. */
	private static final Set<String> FOODS_EATEN_IN_THIRDS = new HashSet<>(Arrays.asList(
		"cake", "chocolate cake", "birthday cake"));

	static
	{
		NAMED_FOOD_PARTS.put("slice of cake", "cake");
		NAMED_FOOD_PARTS.put("chocolate slice", "chocolate cake");
		NAMED_FOOD_PARTS.put("slice of birthday cake", "birthday cake");

		FOOD_PART_PREFIXES.put("half a ", 1);
		FOOD_PART_PREFIXES.put("half an ", 1);
		FOOD_PART_PREFIXES.put("1/2 ", 1);
		FOOD_PART_PREFIXES.put("2/3 ", 2);
	}

	/**
	 * Food eaten in more than one bite, counted in the parts it is eaten in.
	 *
	 * <p>A pie is two halves, a pizza two halves, a cake three slices. Each bite turns the item
	 * into the next smaller one, which the diff sees as one item leaving and another arriving —
	 * the same shape as a dose of potion, and it goes wrong for the same reason if it isn't
	 * counted the same way. In whole items, eating a wild pie is one pie out and one half in:
	 * equal counts, so the transformation guard reads it as nothing consumed and bills none of it,
	 * and the last bite then bills the untradeable half at 0 gp. Three pies eaten cost the task
	 * nothing, while the pies that dropped stayed in the loot column at their full price — both
	 * halves of that were reported.
	 *
	 * <p>In portions a pie is 2 and a half pie is 1, so a bite is a loss of one portion priced at
	 * half of the whole pie, and netting can cancel the pies eaten against the pies dropped.
	 *
	 * @return the portions this item holds, or 0 when it is eaten in one
	 */
	static int portionCount(String name)
	{
		final String lower = name == null ? null : name.toLowerCase(java.util.Locale.ROOT);
		if (lower == null)
		{
			return 0;
		}
		if (NAMED_FOOD_PARTS.containsKey(lower))
		{
			return 1;
		}
		for (Map.Entry<String, Integer> prefix : FOOD_PART_PREFIXES.entrySet())
		{
			if (lower.startsWith(prefix.getKey()))
			{
				return wholeFoodPortions(lower.substring(prefix.getKey().length())) > 1
					? prefix.getValue()
					: 0;
			}
		}
		return wholeFoodPortions(lower);
	}

	/** The whole food a portion belongs to, lower case, or null when the name isn't one. */
	static String portionBaseName(String name)
	{
		final String lower = name == null ? null : name.toLowerCase(java.util.Locale.ROOT);
		if (lower == null)
		{
			return null;
		}
		final String named = NAMED_FOOD_PARTS.get(lower);
		if (named != null)
		{
			return named;
		}
		for (Map.Entry<String, Integer> prefix : FOOD_PART_PREFIXES.entrySet())
		{
			if (lower.startsWith(prefix.getKey()))
			{
				final String whole = lower.substring(prefix.getKey().length());
				return wholeFoodPortions(whole) > 1 ? whole : null;
			}
		}
		return wholeFoodPortions(lower) > 1 ? lower : null;
	}

	/**
	 * Portions a whole food is eaten in, or 0 when it is eaten in one.
	 *
	 * <p>By name, because nothing else distinguishes them: a half pie and a whole one share every
	 * property the client exposes. Pies and pizzas are recognisable by their suffix; the cakes are
	 * listed, since "Dwarven rock cake" is one bite and would be caught by any rule wide enough to
	 * take the others.
	 */
	private static int wholeFoodPortions(String lower)
	{
		if (FOODS_EATEN_IN_THIRDS.contains(lower))
		{
			return 3;
		}
		return lower.endsWith(" pie") || lower.endsWith(" pizza") ? 2 : 0;
	}

	/**
	 * Reads the dose count off a trailing "(n)" in an item name, e.g. "Prayer potion(4)".
	 *
	 * <p>Only digits qualify, so parenthesised suffixes that aren't doses — "(i)", "(tablet)",
	 * "(easy)" — are left alone.
	 *
	 * @return the dose count, or 0 when the name isn't dose-based
	 */
	// Package-private rather than private so the parsing can be tested directly; it's a
	// heuristic over item names and the only part of this class testable without a client.
	static int doseCount(String name)
	{
		if (name.isEmpty() || name.charAt(name.length() - 1) != ')')
		{
			return 0;
		}

		final int open = name.lastIndexOf('(');
		if (open <= 0 || open == name.length() - 2)
		{
			return 0;
		}

		int doses = 0;
		for (int i = open + 1; i < name.length() - 1; i++)
		{
			final char c = name.charAt(i);
			if (c < '0' || c > '9')
			{
				return 0;
			}
			doses = doses * 10 + (c - '0');
		}
		return doses;
	}

	/**
	 * Groups an item with every other form of itself, so an item that transforms rather than
	 * being consumed stays in one family.
	 *
	 * <p>Uses RuneLite's variation table, which already knows that "Trident of the seas (full)",
	 * "Trident of the seas" and "Uncharged trident" are one item in three states — a relationship
	 * no rule over their names could recover, since they share no stem. The name-suffix heuristic
	 * remains as the fallback for items the table doesn't cover.
	 *
	 * @return a key that is stable for one item across all of its forms
	 */
	static String familyKey(int itemId, String name)
	{
		final int variationBase = ItemVariationMapping.map(itemId);
		final Integer spentForm = SPENT_FORMS.get(variationBase);
		if (spentForm != null)
		{
			return "#" + spentForm;
		}
		if (variationBase != itemId || ItemVariationMapping.getVariations(itemId).size() > 1)
		{
			// Prefixed so a variation group can never collide with a plain item name.
			return "#" + variationBase;
		}
		return stripChargeState(name);
	}

	/** Charge-state suffixes that mark the spent form of an otherwise identical item. */
	private static final String[] SPENT_SUFFIXES = {
		" (uncharged)", " (empty)", " (deg)", " (broken)", " (inactive)",
	};

	/** Degradation steps Barrows-style equipment cycles through, as name suffixes. */
	private static final String[] DEGRADE_STEPS = { "100", "75", "50", "25", "0" };

	/**
	 * Strips charge or degradation state from an item name so an item that transforms into a
	 * spent version of itself stays in one family.
	 *
	 * <p>Without this, an item changing id looks like one item vanishing and an unrelated one
	 * appearing. The vanishing side is a value loss and gets billed at the item's <em>full</em>
	 * price — so a Scythe of Vitur running dry would be charged as if the scythe itself had been
	 * consumed. Grouped, the same event correctly costs only the difference between the charged
	 * and uncharged forms.
	 *
	 * <p>Doesn't catch renames that don't share a stem: "Trident of the swamp" becomes
	 * "Uncharged trident", which no suffix rule can connect.
	 */
	static String stripChargeState(String name)
	{
		for (String suffix : SPENT_SUFFIXES)
		{
			if (name.endsWith(suffix))
			{
				return name.substring(0, name.length() - suffix.length());
			}
		}

		final int lastSpace = name.lastIndexOf(' ');
		if (lastSpace > 0)
		{
			final String tail = name.substring(lastSpace + 1);
			for (String step : DEGRADE_STEPS)
			{
				if (tail.equals(step))
				{
					return name.substring(0, lastSpace);
				}
			}
		}

		return name;
	}

	/** Accumulator for one item family within a single diff. */
	private static final class Family
	{
		private long value;
		/** Doses for dose-based families, plain item count otherwise. Negative means consumed. */
		private long units;
		private boolean doseBased;
		/** Whether the family is food eaten in portions rather than a potion counted in doses. */
		private boolean portionFood;
		private int bestDose = -1;
		private int representativeId;
	}

	private static final class DosePrice
	{
		private final int itemId;
		private final int doses;
		private final long fullPrice;

		private DosePrice(int itemId, int doses, long fullPrice)
		{
			this.itemId = itemId;
			this.doses = doses;
			this.fullPrice = fullPrice;
		}
	}

	private Map<Integer, Integer> takeSnapshot()
	{
		final Map<Integer, Integer> out = new HashMap<>();
		addContainer(out, InventoryID.INV);
		addContainer(out, InventoryID.WORN);
		addRunePouch(out);
		addChargeResources(out);
		return out;
	}

	private void addChargeResources(Map<Integer, Integer> out)
	{
		// Blowpipe scales are billed per attack instead — see
		// SlayerTaskLootPlugin.chargeBlowpipeUse(). CHARGES_TOXIC_BLOWPIPE_QUANTITY never moved.
		// Zulrah's scales also charge the serpentine helm, toxic staff of the dead and trident of
		// the swamp, so they are attributed to the item that spent them rather than pooled into
		// one scales row that couldn't be traced back to anything.
		// The sanguinesti staff and both tridents are billed per cast from the powered-staff attack
		// animation instead — see SlayerTaskLootPlugin.POWERED_STAFF_COSTS. Their charge varbits
		// were read here and never moved.

		// Ammunition loaded into a cannon hasn't been spent — it's still the player's until it
		// is fired. Counting the magazine as carried makes loading net to zero against the
		// stack leaving the inventory, and each shot a loss of exactly one ball. Watching
		// cannonball projectiles fly, which is what this replaced, missed the shots entirely
		// whenever the cannon's position wasn't established.
		addSynthetic(out, loadedCannonballId, client.getVarpValue(VarPlayerID.ROCKTHROWER), 1);

		// The tome of fire is billed per cast from its spell graphic — see
		// SlayerTaskLootPlugin.onGraphicChanged().

		// The venator bow's ancient essence is charged per attack animation instead — see
		// SlayerTaskLootPlugin.processRepeatingWeaponUsage(). CHARGES_VENATOR_BOW_QUANTITY was
		// read here and never once moved in game.

		// Sunfire splinters are counted from the quiver's ammunition falling, and the eye of ayak
		// from its attack animation — see SlayerTaskLootPlugin. Every CHARGES_*_QUANTITY varbit
		// this class once read was measured at zero and never moved; none of them is populated,
		// so nothing is read from that block any more.

		final int quiverAmmoId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		final int quiverAmmo = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
		if (quiverAmmoId > 0 && quiverAmmo > 0)
		{
			out.merge(itemManager.canonicalize(quiverAmmoId), quiverAmmo, Integer::sum);
		}
	}

	private static void addSynthetic(Map<Integer, Integer> out, int itemId, int charges, int perCharge)
	{
		if (charges > 0)
		{
			out.merge(itemId, charges * perCharge, Integer::sum);
		}
	}

	private void addContainer(Map<Integer, Integer> out, int containerId)
	{
		final ItemContainer container = client.getItemContainer(containerId);
		if (container == null)
		{
			return;
		}

		for (Item item : container.getItems())
		{
			final int id = item.getId();
			if (id <= 0 || item.getQuantity() <= 0 || DEPLOYABLE_ITEMS.contains(id))
			{
				continue;
			}
			// Noted stacks price the same as the base item, and resolving them keeps a
			// withdraw-as-note from looking like a different item than what gets used.
			out.merge(itemManager.canonicalize(id), item.getQuantity(), Integer::sum);
		}
	}

	/**
	 * The pouch as the snapshot sees it, slot by slot, including slots it decided to skip.
	 *
	 * <p>Runes moving from the inventory into the pouch should be invisible to a charge: both
	 * sides are in one snapshot keyed by item id, so the transfer nets to zero and no family is
	 * ever built. A charge for pouched runes therefore means this read came back missing them,
	 * and only the raw slot values say which of type, quantity or the enum lookup was the one
	 * that failed.
	 */
	private void logRunePouch()
	{
		final EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runes == null)
		{
			log.debug("  pouch enum RUNEPOUCH_RUNE unavailable, pouch contributed nothing");
			return;
		}
		for (int slot = 0; slot < RUNE_POUCH_TYPE_VARBITS.length; slot++)
		{
			final int type = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[slot]);
			final int quantity = client.getVarbitValue(RUNE_POUCH_QUANTITY_VARBITS[slot]);
			if (type == 0 && quantity == 0)
			{
				continue;
			}
			log.debug("  pouch slot {} type {} -> item {} x{}", slot + 1, type,
				runes.getIntValue(type), quantity);
		}
	}

	private void addRunePouch(Map<Integer, Integer> out)
	{
		final EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runes == null)
		{
			return;
		}

		for (int slot = 0; slot < RUNE_POUCH_TYPE_VARBITS.length; slot++)
		{
			final int type = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[slot]);
			final int quantity = client.getVarbitValue(RUNE_POUCH_QUANTITY_VARBITS[slot]);
			if (type == 0 || quantity <= 0)
			{
				continue;
			}

			final int itemId = runes.getIntValue(type);
			if (itemId > 0)
			{
				out.merge(itemId, quantity, Integer::sum);
			}
		}
	}
}

package com.slayertaskloot;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Getter;

/**
 * One user-visible session within a Slayer assignment.
 *
 * <p>A session may contain several active segments. Manually resuming a closed session adds
 * another segment to the same session rather than creating a second user-visible total.
 */
@Getter
class TaskSession
{
	private String sessionId;
	private long startedAt;
	private long endedAt;
	private List<SessionSegment> segments;
	private int kills;
	private Map<Integer, Integer> items;
	private Map<Integer, Long> itemValues;
	private long supplyCost;
	private Map<Integer, SupplyEntry> supplies;

	/** Gson. */
	TaskSession()
	{
	}

	TaskSession(String sessionId, long startedAt, boolean openedManually)
	{
		this.sessionId = sessionId;
		this.startedAt = startedAt;
		this.segments = new ArrayList<>();
		this.items = new LinkedHashMap<>();
		this.itemValues = new LinkedHashMap<>();
		this.supplies = new LinkedHashMap<>();
		openSegment(startedAt, openedManually);
	}

	List<SessionSegment> getSegments()
	{
		if (segments == null)
		{
			segments = new ArrayList<>();
		}
		return segments;
	}

	Map<Integer, Integer> getItems()
	{
		if (items == null)
		{
			items = new LinkedHashMap<>();
		}
		return items;
	}

	Map<Integer, SupplyEntry> getSupplies()
	{
		if (supplies == null)
		{
			supplies = new LinkedHashMap<>();
		}
		return supplies;
	}

	Map<Integer, Long> getItemValues()
	{
		if (itemValues == null)
		{
			itemValues = new LinkedHashMap<>();
		}
		return itemValues;
	}

	void addKills(int count)
	{
		kills += count;
	}

	void addItem(int itemId, int quantity)
	{
		getItems().merge(itemId, quantity, Integer::sum);
	}

	void addItem(int itemId, int quantity, long value)
	{
		addItem(itemId, quantity);
		getItemValues().merge(itemId, value, Long::sum);
	}

	void addSupplyCharge(SupplyCharge charge)
	{
		supplyCost += charge.getTotal();
		for (SupplyCharge.Row row : charge.getRows())
		{
			final SupplyEntry existing = getSupplies().get(row.getItemId());
			if (existing == null)
			{
				getSupplies().put(row.getItemId(),
					new SupplyEntry(row.getQuantity(), row.getValue(), row.isDoseBased(),
						row.getComponentHundredths()));
			}
			else
			{
				existing.add(row.getQuantity(), row.getValue(), row.getComponentHundredths());
			}
		}
	}

	boolean isOpen()
	{
		return !getSegments().isEmpty()
			&& getSegments().get(getSegments().size() - 1).getEndedAt() == 0;
	}

	void resume(long now)
	{
		resume(now, true);
	}

	void resume(long now, boolean openedManually)
	{
		if (!isOpen())
		{
			endedAt = 0;
			openSegment(now, openedManually);
		}
	}

	/** Why the most recent segment ended, or null while it is still running. */
	String lastCloseReason()
	{
		return isOpen() ? null : getSegments().get(getSegments().size() - 1).getCloseReason();
	}

	void close(long now, String reason)
	{
		if (!isOpen())
		{
			return;
		}

		getSegments().get(getSegments().size() - 1).close(now, reason);
		endedAt = now;
	}

	void tick()
	{
		if (isOpen())
		{
			getSegments().get(getSegments().size() - 1).tick();
		}
	}

	int getOnTaskTicks()
	{
		return getSegments().stream().mapToInt(SessionSegment::getOnTaskTicks).sum();
	}

	void mergeFrom(TaskSession other)
	{
		getSegments().addAll(other.getSegments());
		getSegments().sort(Comparator.comparingLong(SessionSegment::getStartedAt));
		startedAt = Math.min(startedAt, other.startedAt);
		endedAt = Math.max(endedAt, other.endedAt);
		kills += other.kills;
		other.getItems().forEach((itemId, quantity) ->
			getItems().merge(itemId, quantity, Integer::sum));
		other.getItemValues().forEach((itemId, value) ->
			getItemValues().merge(itemId, value, Long::sum));
		supplyCost += other.supplyCost;
		other.getSupplies().forEach((itemId, supply) ->
		{
			final SupplyEntry existing = getSupplies().get(itemId);
			if (existing == null)
			{
				getSupplies().put(itemId,
					new SupplyEntry(supply.getQuantity(), supply.getValue(), supply.isDoseBased(),
						supply.getComponentHundredths()));
			}
			else
			{
				existing.add(supply.getQuantity(), supply.getValue(), supply.getComponentHundredths());
			}
		});
	}

	private void openSegment(long now, boolean openedManually)
	{
		getSegments().add(new SessionSegment(now, openedManually));
	}

	@Getter
	static class SessionSegment
	{
		private long startedAt;
		private long endedAt;
		private int onTaskTicks;
		private boolean openedManually;
		private String closeReason;

		/** Gson. */
		SessionSegment()
		{
		}

		SessionSegment(long startedAt, boolean openedManually)
		{
			this.startedAt = startedAt;
			this.openedManually = openedManually;
		}

		void tick()
		{
			onTaskTicks++;
		}

		void close(long now, String reason)
		{
			endedAt = now;
			closeReason = reason;
		}
	}
}

package com.slayertaskloot;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.Value;

/**
 * What one supply diff cost, plus the breakdown of what was actually used up.
 *
 * <p>{@link #total} is the sum of every row's value, so a breakdown always adds up to the
 * figure shown next to it.
 */
@Value
class SupplyCharge
{
	static final SupplyCharge EMPTY = new SupplyCharge(0, Collections.emptyList());

	/**
	 * Component quantities are held in hundredths of an item, so that a use spending a fraction
	 * of one — a scythe swing against a vial of blood — is representable at the moment it happens
	 * rather than only once a hundred of them have added up to a whole item.
	 */
	static final int COMPONENT_SCALE = 100;

	long total;
	List<Row> rows;

	boolean isEmpty()
	{
		return total <= 0 && rows.isEmpty();
	}

	/**
	 * One consumed item family.
	 *
	 * @param itemId    representative id for the family — the largest dose variant for
	 *                  dose-based items, so the icon is the familiar one
	 * @param quantity  doses for dose-based families, plain item count otherwise
	 * @param doseBased whether {@link #quantity} counts doses rather than whole items
	 */
	@Value
	static class Row
	{
		int itemId;
		int quantity;
		long value;
		boolean doseBased;

		/**
		 * What one use of a charged item cost, as component itemId -> {@link #COMPONENT_SCALE}ths
		 * of an item, or empty for an ordinary supply.
		 *
		 * <p>When present, {@link #itemId} is the charged item itself and {@link #quantity} counts
		 * its uses, so the row reads "Scythe of Vitur, 400 attacks" with the blood runes and vials
		 * behind it rather than as separate supplies. Grouping them keeps a weapon's running cost
		 * as one line that can be compared against the drops, instead of scattering it across
		 * rune rows that look like spellcasting.
		 */
		Map<Integer, Integer> componentHundredths;

		Row(int itemId, int quantity, long value, boolean doseBased)
		{
			this(itemId, quantity, value, doseBased, Collections.emptyMap());
		}

		Row(int itemId, int quantity, long value, boolean doseBased,
			Map<Integer, Integer> componentHundredths)
		{
			this.itemId = itemId;
			this.quantity = quantity;
			this.value = value;
			this.doseBased = doseBased;
			this.componentHundredths = componentHundredths;
		}
	}
}

