	void display(TaskView current, List<TaskView> past)
	{
		this.currentTask = current;
		this.history = past == null ? Collections.emptyList() : past;
		rebuild();
	}

	private void rebuild()
	{
		rebuildCurrent();
		rebuildHistory();
	}

	private void rebuildCurrent()
	{
		currentContainer.removeAll();

		if (currentTask == null)
		{
			currentContainer.add(placeholder("No slayer task assigned."));
		}
		else
		{
			currentContainer.add(buildTaskBox(currentTask, true));
		}

		currentContainer.revalidate();
		currentContainer.repaint();
		revalidate();
		repaint();
	}

	private int closedSessionCount()
	{
		if (currentTask == null)
		{
			return 0;
		}
		int count = 0;
		for (TaskView.SessionView session : currentTask.getSessionViews())
		{
			if (!session.isOpen())
			{
				count++;
			}
		}
		return count;
	}

	private void mergeSessions()
	{
		final List<TaskView.SessionView> closed = new java.util.ArrayList<>();
		for (TaskView.SessionView session : currentTask.getSessionViews())
		{
			if (!session.isOpen())
			{
				closed.add(session);
			}
		}

		final TaskView.SessionView source = (TaskView.SessionView) JOptionPane.showInputDialog(
			this, "Select the session to combine:", "Merge sessions",
			JOptionPane.PLAIN_MESSAGE, null, closed.toArray(), closed.get(closed.size() - 1));
		if (source == null)
		{
			return;
		}

		closed.remove(source);
		final TaskView.SessionView target = (TaskView.SessionView) JOptionPane.showInputDialog(
			this, "Combine it into:", "Merge sessions",
			JOptionPane.PLAIN_MESSAGE, null, closed.toArray(), closed.get(closed.size() - 1));
		if (target != null)
		{
			plugin.mergeSessions(source.getSessionId(), target.getSessionId());
		}
	}

	private void resumeSession()
	{
		final List<TaskView.SessionView> closed = new java.util.ArrayList<>();
		for (TaskView.SessionView session : currentTask.getSessionViews())
		{
			if (!session.isOpen())
			{
				closed.add(session);
			}
		}
		if (closed.isEmpty())
		{
			return;
		}

		final TaskView.SessionView selected = closed.size() == 1
			? closed.get(0)
			: (TaskView.SessionView) JOptionPane.showInputDialog(
				this, "Select the session to resume:", "Resume session",
				JOptionPane.PLAIN_MESSAGE, null, closed.toArray(), closed.get(closed.size() - 1));
		if (selected != null)
		{
			plugin.resumeSession(selected.getSessionId());
		}
	}

	private void rebuildHistory()
	{
		historyContainer.removeAll();

		if (history.isEmpty())
		{
			historyHeaderLabel.setText("No completed tasks yet.");
			historyContainer.add(placeholder("Finished tasks will appear here."));
		}
		else
		{
			long totalLoot = 0;
			long totalSupplies = 0;
			for (TaskView task : history)
			{
				totalLoot += task.getLootValue();
				totalSupplies += task.getSupplyCost();
			}

			final long total = config.trackSupplies()
				? totalLoot - totalSupplies
				: totalLoot;

			historyHeaderLabel.setText(history.size() + " tasks · " + gp(total) + " total");

			for (TaskView task : history)
			{
				historyContainer.add(buildTaskBox(task, false));
			}
		}

		historyContainer.revalidate();
		historyContainer.repaint();
	}

	private JLabel placeholder(String text)
	{
		final JLabel label = new JLabel(text, SwingConstants.CENTER);
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Color.GRAY);
		label.setBorder(new EmptyBorder(16, 8, 16, 8));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private JPanel buildTaskBox(TaskView task, boolean isCurrent)
	{
		final JPanel box = new JPanel();
		// DynamicGridLayout gives every row the card's full width. BoxLayout respects each
		// row's preferred/maximum width and can recenter the entire card as sections expand.
		box.setLayout(new DynamicGridLayout(0, 1));
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(new EmptyBorder(6, 6, 6, 6));
		box.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JPanel title = row(task.getTaskName(), null, Color.WHITE,
			FontManager.getRunescapeBoldFont());
		title.add(isCurrent ? currentActions(task) : historyActions(task), BorderLayout.EAST);
		box.add(title);

		if (task.getTaskLocation() != null)
		{
			box.add(row(task.getTaskLocation(), null, Color.LIGHT_GRAY, FontManager.getRunescapeSmallFont()));
		}

		// Deliberately "tracked" rather than a progress fraction against the assignment size.
		// Enabling the plugin partway through a task starts this at zero while the game's own
		// counter is already down, and implying otherwise would just look broken.
		final String killLine = task.getKills() + (task.getKills() == 1 ? " kill" : " kills")
			+ " tracked · " + formatDuration(task.getOnTaskTicks());
		final JPanel killRow = row(killLine, null, Color.LIGHT_GRAY, FontManager.getRunescapeSmallFont());
		if (task.getAttributedKills() < task.getKills())
		{
			// The count comes from the slayer counter; sessions only hold the kills that could be
			// matched to a death the client saw. Surfaced rather than hidden, because the shortfall
			// is exactly the set of kills whose drops may have landed on the wrong session.
			killRow.setToolTipText(task.getAttributedKills() + " of "
				+ task.getKills() + " matched to a session");
		}
		box.add(killRow);

		// Sessions are shown so the supply attribution can be sanity-checked rather than
		// taken on trust — "3 sessions, 47 min on task" is checkable against reality.
		final String sessionLine = task.getSessions()
			+ (task.getSessions() == 1 ? " session" : " sessions");
		box.add(row(sessionLine, null, Color.GRAY, FontManager.getRunescapeSmallFont()));

		if (!isCurrent && task.getEndedAt() > 0)
		{
			box.add(row(TIMESTAMP_FMT.format(Instant.ofEpochMilli(task.getEndedAt())
				.atZone(ZoneId.systemDefault())), null, Color.GRAY, FontManager.getRunescapeSmallFont()));
		}
		box.add(separator());

		// Each section owns what it totals: the drops header sits directly above the drops it
		// adds up, and supplies below them. Reading a total and then having to look elsewhere
		// for the items behind it was the confusing part of showing all three totals together.
		box.add(collapsibleHeader("Drops", dropsExpanded, gp(task.getLootValue()), PROFIT_GREEN,
			() -> dropsExpanded = !dropsExpanded));

		if (dropsExpanded && !task.getRows().isEmpty())
		{
			box.add(buildItemGrid(task));
		}
		if (dropsExpanded && !task.getExcludedDrops().isEmpty())
		{
			box.add(buildExcludedDropsControl(task));
		}

		if (config.trackSupplies())
		{
			box.add(separator());
			box.add(collapsibleHeader("Supplies", suppliesExpanded, "-" + gp(task.getSupplyCost()),
				SUPPLY_ORANGE, () -> suppliesExpanded = !suppliesExpanded));

			// Breakdown of the line above. Sums to it exactly, since both come from the
			// same per-family diff.
			if (suppliesExpanded)
			{
				for (TaskView.LootRow supply : task.getSupplyRows())
				{
					box.add(supplyBreakdownRow(supply));
				}
			}

			// Last, under everything it's derived from.
			box.add(separator());
			final long net = task.getLootValue() - task.getSupplyCost();
			box.add(row("Profit", gp(net), net >= 0 ? PROFIT_GREEN : LOSS_RED,
				FontManager.getRunescapeBoldFont()));
		}

		final JPanel spaced = new JPanel(new BorderLayout());
		spaced.setBackground(ColorScheme.DARK_GRAY_COLOR);
		spaced.setBorder(new EmptyBorder(0, 0, 6, 0));
		spaced.setAlignmentX(Component.LEFT_ALIGNMENT);
		spaced.add(box, BorderLayout.CENTER);
		return spaced;
	}

	private JPanel currentActions(TaskView task)
	{
		final JPanel actions = actionToolbar();
		if (task.isSessionOpen())
		{
			final JButton pause = iconButton(PAUSE_ICON, PAUSE_ICON_HOVER, "End current session");
			pause.addActionListener(e -> plugin.endCurrentSession());
			actions.add(pause);
		}
		else if (!task.isCompleted())
		{
			final JButton start = iconButton(START_ICON, START_ICON_HOVER, "Start a new session");
			start.addActionListener(e -> plugin.startNewSession());
			actions.add(start);

			final JButton resume = iconButton(RESUME_ICON, RESUME_ICON_HOVER,
				task.isCanResumeSession()
				? "Resume a closed session and pool new activity into it"
				: "No closed session is available to resume");
			resume.setEnabled(task.isCanResumeSession());
			resume.addActionListener(e -> resumeSession());
			actions.add(resume);

			final JButton merge = iconButton(MERGE_ICON, MERGE_ICON_HOVER,
				closedSessionCount() >= 2
				? "Merge two closed sessions"
				: "At least two closed sessions are required");
			merge.setEnabled(closedSessionCount() >= 2);
			merge.addActionListener(e -> mergeSessions());
			actions.add(merge);
		}

		final JButton reset = iconButton(DELETE_ICON, DELETE_ICON_HOVER, "Reset current task record");
		reset.addActionListener(e ->
		{
			final int answer = JOptionPane.showConfirmDialog(this,
				"Reset the current " + task.getTaskName() + " record?",
				"Reset current task", JOptionPane.YES_NO_OPTION);
			if (answer == JOptionPane.YES_OPTION)
			{
				plugin.resetActiveTask();
			}
		});
		actions.add(reset);
		return actions;
	}

	private JPanel historyActions(TaskView task)
	{
		final JPanel actions = actionToolbar();

		final boolean canResume = currentTask != null && !currentTask.isCompleted()
			&& sameTask(currentTask, task);
		final JButton resume = iconButton(START_ICON, START_ICON_HOVER,
			canResume ? "Pool this record into the current matching task"
				: "Requires an active task with the same monster and location");
		resume.setEnabled(canResume);
		resume.addActionListener(e -> plugin.poolHistoryIntoCurrent(task.getAssignmentId()));
		actions.add(resume);

		final List<TaskView> mergeCandidates = new java.util.ArrayList<>();
		for (TaskView candidate : history)
		{
			if (!candidate.getAssignmentId().equals(task.getAssignmentId())
				&& sameTask(candidate, task))
			{
				mergeCandidates.add(candidate);
			}
		}
		final JButton merge = iconButton(MERGE_ICON, MERGE_ICON_HOVER,
			mergeCandidates.isEmpty()
			? "No other matching history record is available"
			: "Combine all " + mergeCandidates.size() + " other matching "
				+ (mergeCandidates.size() == 1 ? "record" : "records") + " into this one");
		merge.setEnabled(!mergeCandidates.isEmpty());
		merge.addActionListener(e -> mergeHistoryTask(task, mergeCandidates));
		actions.add(merge);

		final JButton delete = iconButton(DELETE_ICON, DELETE_ICON_HOVER,
			"Delete this history record");
		delete.addActionListener(e ->
		{
			final int answer = JOptionPane.showConfirmDialog(this,
				"Delete this " + task.getTaskName() + " record?",
				"Delete task history", JOptionPane.YES_NO_OPTION);
			if (answer == JOptionPane.YES_OPTION)
			{
				plugin.deleteHistoryTask(task.getAssignmentId());
			}
		});
		actions.add(delete);
		return actions;
	}

	private static JPanel actionToolbar()
	{
		final JPanel actions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 3, 0));
		actions.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		return actions;
	}

	private static JButton iconButton(Icon icon, Icon rollover, String tooltip)
	{
		final JButton button = new JButton(icon);
		button.setRolloverIcon(rollover);
		button.setToolTipText(tooltip);
		button.setPreferredSize(new Dimension(18, 16));
		SwingUtil.removeButtonDecorations(button);
		return button;
	}

	/**
	 * The section arrow, drawn as a filled triangle rather than a Unicode glyph.
	 *
	 * <p>The RuneScape font has no triangle characters, so a literal "▸"/"▾" only renders when the
	 * user's machine happens to have a fallback font that covers it — otherwise it shows as a tofu
	 * box. Drawing the shape ourselves makes the arrow look the same on every install.
	 */
	private static BufferedImage buildArrowIcon(boolean expanded)
	{
		final BufferedImage image = new BufferedImage(8, 8, BufferedImage.TYPE_INT_ARGB);
		final java.awt.Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
			java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(Color.LIGHT_GRAY);
		final java.awt.Polygon triangle = new java.awt.Polygon();
		if (expanded)
		{
			// Pointing down.
			triangle.addPoint(1, 2);
			triangle.addPoint(7, 2);
			triangle.addPoint(4, 6);
		}
		else
		{
			// Pointing right.
			triangle.addPoint(2, 1);
			triangle.addPoint(6, 4);
			triangle.addPoint(2, 7);
		}
		graphics.fillPolygon(triangle);
		graphics.dispose();
		return image;
	}

	private static BufferedImage buildMergeIcon()
	{
		final BufferedImage image = new BufferedImage(14, 14, BufferedImage.TYPE_INT_ARGB);
		final java.awt.Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING,
			java.awt.RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setColor(new Color(170, 170, 170));
		graphics.drawLine(2, 4, 11, 4);
		graphics.drawLine(8, 1, 11, 4);
		graphics.drawLine(8, 7, 11, 4);
		graphics.drawLine(11, 10, 2, 10);
		graphics.drawLine(5, 7, 2, 10);
		graphics.drawLine(5, 13, 2, 10);
		graphics.dispose();
		return image;
	}

	/**
	 * Pools every matching record into this one, after confirming how many that is.
	 *
	 * <p>Confirmed rather than done outright because a merge can't be undone from the panel:
	 * the sources are folded in and dropped, and separating them again would mean knowing which
	 * kill and which drop came from where, which nothing records.
	 */
	private void mergeHistoryTask(TaskView target, List<TaskView> candidates)
	{
		final int answer = JOptionPane.showConfirmDialog(this,
			"Combine " + candidates.size() + " other " + target.getTaskName() + " "
				+ (candidates.size() == 1 ? "record" : "records") + " into this one?"
				+ "\nThis cannot be undone.",
			"Merge task history", JOptionPane.YES_NO_OPTION);
		if (answer == JOptionPane.YES_OPTION)
		{
			plugin.mergeAllHistoryTasks(target.getAssignmentId());
		}
	}

	/** Matches on the monster alone — see SlayerTaskLootPlugin.sameTask(), which must agree. */
	private static boolean sameTask(TaskView left, TaskView right)
	{
		return Objects.equals(left.getTaskName(), right.getTaskName());
	}

	/** A section total whose arrow shows and hides the entries making it up. */
	private JPanel collapsibleHeader(String label, boolean expanded, String value, Color valueColor,
		Runnable onToggle)
	{
		final JPanel panel = new JPanel(new BorderLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JButton toggle = new JButton(label);
		toggle.setIcon(expanded ? EXPANDED_ICON : COLLAPSED_ICON);
		toggle.setIconTextGap(4);
		toggle.setFont(FontManager.getRunescapeSmallFont());
		toggle.setForeground(Color.LIGHT_GRAY);
		toggle.setBorderPainted(false);
		toggle.setContentAreaFilled(false);
		toggle.setFocusPainted(false);
		toggle.setHorizontalAlignment(SwingConstants.LEFT);
		toggle.setBorder(BorderFactory.createEmptyBorder());
		toggle.addActionListener(e ->
		{
			onToggle.run();
			rebuild();
		});
		panel.add(toggle, BorderLayout.WEST);

		final JLabel valueLabel = new JLabel(value);
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		valueLabel.setForeground(valueColor);
		panel.add(valueLabel, BorderLayout.EAST);
		return panel;
	}

	private JPanel buildItemGrid(TaskView task)
	{
		final JPanel list = new JPanel();
		list.setLayout(new GridLayout(0, 1, 0, 2));
		list.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		list.setAlignmentX(Component.LEFT_ALIGNMENT);

		for (TaskView.LootRow item : task.getRows())
		{
			list.add(buildItemRow(task, item));
		}

		return list;
	}

	private JPanel buildItemRow(TaskView task, TaskView.LootRow item)
	{
		final JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		final JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(32, 32));
		final AsyncBufferedImage image = itemManager.getImage(
			item.getItemId(), item.getQuantity(), item.getQuantity() > 1);
		image.addTo(icon);
		row.add(icon, BorderLayout.WEST);

		final JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		final JLabel name = new JLabel(item.getName());
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(Color.WHITE);
		text.add(name);

		final StringBuilder detail = new StringBuilder();
		if (item.getQuantity() > 1)
		{
			detail.append('x').append(QuantityFormatter.quantityToStackSize(item.getQuantity()));
		}
		if (config.showItemValues())
		{
			if (detail.length() > 0)
			{
				detail.append("  ");
			}
			detail.append(gp(item.getValue()));
		}

		if (detail.length() > 0)
		{
			final JLabel sub = new JLabel(detail.toString());
			sub.setFont(FontManager.getRunescapeSmallFont());
			sub.setForeground(Color.LIGHT_GRAY);
			text.add(sub);
		}

		row.add(text, BorderLayout.CENTER);
		row.setToolTipText(item.getName() + " — " + QuantityFormatter.formatNumber(item.getValue()) + " gp");

		final JPopupMenu menu = new JPopupMenu();
		final JMenuItem excludeTask = new JMenuItem("Exclude from task");
		excludeTask.addActionListener(e ->
			plugin.excludeDropForTask(task.getTaskName(), item.getName()));
		menu.add(excludeTask);
		final JMenuItem excludeAll = new JMenuItem("Exclude from all tasks");
		excludeAll.addActionListener(e -> plugin.excludeDropFromAllTasks(item.getName()));
		menu.add(excludeAll);
		installPopup(row, menu);

		return row;
	}

	private JPanel buildExcludedDropsControl(TaskView task)
	{
		final JButton manage = new JButton(task.getExcludedDrops().size() == 1
			? "1 excluded drop"
			: task.getExcludedDrops().size() + " excluded drops");
		manage.setFont(FontManager.getRunescapeSmallFont());
		manage.setForeground(Color.LIGHT_GRAY);
		manage.setToolTipText("Choose an excluded drop to include again");
		manage.setHorizontalAlignment(SwingConstants.LEFT);
		SwingUtil.removeButtonDecorations(manage);
		manage.addActionListener(e ->
		{
			final TaskView.ExcludedDrop selected = (TaskView.ExcludedDrop) JOptionPane.showInputDialog(
				this, "Choose a drop to include again:", "Excluded drops",
				JOptionPane.PLAIN_MESSAGE, null, task.getExcludedDrops().toArray(),
				task.getExcludedDrops().get(0));
			if (selected == null)
			{
				return;
			}
			if (selected.isGlobal())
			{
				plugin.includeDropForAllTasks(selected.getName());
			}
			else
			{
				plugin.includeDropForTask(task.getTaskName(), selected.getName());
			}
		});

		final JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.add(manage, BorderLayout.CENTER);
		return row;
	}

	private static void installPopup(JComponent component, JPopupMenu menu)
	{
		component.setComponentPopupMenu(menu);
		installPopupChildren(component);
	}

	private static void installPopupChildren(JComponent component)
	{
		for (Component child : component.getComponents())
		{
			if (child instanceof JComponent)
			{
				((JComponent) child).setInheritsPopupMenu(true);
				installPopupChildren((JComponent) child);
			}
		}
	}

	/**
	 * One indented line under the Supplies total, e.g. "Prayer potion  x14 doses" against
	 * its cost. Text-only and compact deliberately — with icons this list would dwarf the
	 * loot it's meant to be a footnote to.
	 */
	private static JPanel supplyBreakdownRow(TaskView.LootRow supply)
	{
		final JPanel panel = new JPanel(new BorderLayout(4, 0));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		final StringBuilder left = new StringBuilder("   ").append(supply.getName());
		if (supply.getQuantity() > 0)
		{
			left.append("  x").append(QuantityFormatter.quantityToStackSize(supply.getQuantity()));
			if (!supply.getUnit().isEmpty())
			{
				left.append(' ').append(supply.getUnit());
			}
		}

		final JLabel nameLabel = new JLabel(left.toString());
		nameLabel.setFont(FontManager.getRunescapeSmallFont());
		nameLabel.setForeground(Color.GRAY);
		// CENTER is allowed to shrink when the sidebar is narrow. WEST would retain the
		// label's full preferred width and make the entire scrollable card grow sideways.
		panel.add(nameLabel, BorderLayout.CENTER);

		final JLabel valueLabel = new JLabel(gp(supply.getValue()));
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		valueLabel.setForeground(Color.GRAY);
		panel.add(valueLabel, BorderLayout.EAST);

		// A charged item is one line for the weapon, with what its charges actually cost on hover.
		// Listing every rune and vial as its own supply made a scythe look like spellcasting and
		// buried the potions and food underneath it.
		if (!supply.getBreakdown().isEmpty())
		{
			final StringBuilder tooltip = new StringBuilder("<html>").append(supply.getName());
			for (String component : supply.getBreakdown())
			{
				tooltip.append("<br>&nbsp;&nbsp;").append(component);
			}
			panel.setToolTipText(tooltip.append("</html>").toString());
			nameLabel.setToolTipText(panel.getToolTipText());
		}

		return panel;
	}

	/** A label line, optionally with a right-aligned value. */
	private static JPanel row(String left, String right, Color color, Font font)
	{
		final JPanel panel = new JPanel(new BorderLayout());
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JLabel leftLabel = new JLabel(left);
		leftLabel.setFont(font);
		leftLabel.setForeground(right == null ? color : Color.LIGHT_GRAY);
		panel.add(leftLabel, BorderLayout.CENTER);

		if (right != null)
		{
			final JLabel rightLabel = new JLabel(right);
			rightLabel.setFont(font);
			rightLabel.setForeground(color);
			panel.add(rightLabel, BorderLayout.EAST);
		}

		return panel;
	}

	private static JPanel separator()
	{
		final JPanel line = new JPanel();
		line.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		line.setBorder(new MatteBorder(1, 0, 0, 0, ColorScheme.MEDIUM_GRAY_COLOR));
		line.setPreferredSize(new Dimension(0, 5));
		line.setAlignmentX(Component.LEFT_ALIGNMENT);
		return line;
	}

	private static String gp(long value)
	{
		final String formatted = QuantityFormatter.quantityToStackSize(Math.abs(value));
		return (value < 0 ? "-" : "") + formatted + " gp";
	}

	/** Formats on-task game ticks as h:mm:ss / m:ss. */
	private static String formatDuration(int ticks)
	{
		final long totalSeconds = (long) ticks * 600 / 1000;
		final long hours = totalSeconds / 3600;
		final long minutes = (totalSeconds % 3600) / 60;
		final long seconds = totalSeconds % 60;

		return hours > 0
			? String.format("%d:%02d:%02d", hours, minutes, seconds)
			: String.format("%d:%02d", minutes, seconds);
	}

	/** Keeps scroll contents at the sidebar width instead of following their widest label. */
	private static final class ViewportWidthPanel extends JPanel implements Scrollable
	{
		private ViewportWidthPanel(LayoutManager layout)
		{
			super(layout);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return Math.max(16, visibleRect.height - 16);
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

package com.slayertaskloot;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import javax.annotation.Nullable;
import lombok.Getter;
import lombok.Setter;

/**
 * One slayer task assignment and everything credited to it.
 *
 * <p>Persisted to per-character config as JSON, so every field has to stay Gson-friendly
 * and the class needs a no-argument constructor. Fields may come back null from an older
 * stored snapshot, so readers defend against that rather than assuming initialisers ran.
 */
@Getter
class TaskLootRecord
{
	/** Stable identity for this assignment, including back-to-back assignments of the same type. */
	private String assignmentId;

	/** Task name as resolved from the slayer DB table, e.g. "Aberrant spectres". */
	private String taskName;

	/** Konar assignment area, or null for masters that don't assign one. */
	@Nullable
	private String taskLocation;

	/** Size of the assignment when it was handed out. */
	private int initialAmount;

	/**
	 * Kills attributed to a specific death the client observed, and therefore to a session.
	 * Not the task's kill count — see {@link #counterKills} for why it can fall short of it.
	 */
	private int kills;

	/**
	 * Kills counted straight off the slayer counter, which is the only exact signal available:
	 * it moves once per kill that counted toward the assignment, and for nothing else.
	 *
	 * <p>Kept separately from {@link #kills} because the two answer different questions.
	 * A kill is only added to {@code kills} once a scene-observed death has been matched to it
	 * within a couple of ticks, which is what decides the <em>session</em> a kill and its drops
	 * belong to. That match legitimately fails — a despawn seen outside the window, a death the
	 * client never saw — and when it does the kill is unattributable but has still happened.
	 * Counting it here means a failed match costs the drops' session attribution, not the kill.
	 *
	 * <p>Only movement actually observed is counted, so enabling the plugin midway through an
	 * assignment credits the kills from that point rather than the whole counter.
	 */
	private int counterKills;

	/** Epoch millis when this assignment was first seen. */
	private long startedAt;

	/** Epoch millis when the counter reached zero, or 0 while still in progress. */
	@Setter
	private long endedAt;

	/** itemId -> total quantity. Insertion-ordered so first-seen order stays stable. */
	private Map<Integer, Integer> items;
	private Map<Integer, Long> itemValues;

	/** GE value of supplies consumed during this task's sessions. */
	private long supplyCost;

	/**
	 * Breakdown of {@link #supplyCost}: representative itemId -> what that family cost.
	 * Always sums to {@code supplyCost}, since both come from the same per-family diff.
	 */
	private Map<Integer, SupplyEntry> supplies;

	/** Number of on-task sessions opened. Surfaced so the attribution is auditable. */
	private int sessions;

	/** Game ticks spent with a session open, i.e. time actually on task. */
	private int onTaskTicks;

	/** User-visible sessions. A manually resumed session may contain multiple active segments. */
	private List<TaskSession> taskSessions;

	/** Gson. */
	TaskLootRecord()
	{
	}

	TaskLootRecord(String taskName, @Nullable String taskLocation, int initialAmount, long startedAt)
	{
		this.assignmentId = UUID.randomUUID().toString();
		this.taskName = taskName;
		this.taskLocation = taskLocation;
		this.initialAmount = initialAmount;
		this.startedAt = startedAt;
		this.items = new LinkedHashMap<>();
		this.itemValues = new LinkedHashMap<>();
		this.supplies = new LinkedHashMap<>();
		this.taskSessions = new ArrayList<>();
	}

	String getAssignmentId()
	{
		if (assignmentId == null || assignmentId.isEmpty())
		{
			assignmentId = UUID.randomUUID().toString();
		}
		return assignmentId;
	}

	List<TaskSession> getTaskSessions()
	{
		if (taskSessions == null)
		{
			taskSessions = new ArrayList<>();
		}
		return taskSessions;
	}

	Map<Integer, Integer> getItems()
	{
		ensureLegacyItems();
		final Map<Integer, Integer> combined = new LinkedHashMap<>(items);
		for (TaskSession session : getTaskSessions())
		{
			session.getItems().forEach((itemId, quantity) ->
				combined.merge(itemId, quantity, Integer::sum));
		}
		return combined;
	}

	Map<Integer, SupplyEntry> getSupplies()
	{
		ensureLegacySupplies();
		final Map<Integer, SupplyEntry> combined = new LinkedHashMap<>();
		supplies.forEach((itemId, supply) -> combined.put(itemId,
			new SupplyEntry(supply.getQuantity(), supply.getValue(), supply.isDoseBased(),
						supply.getComponentHundredths())));
		for (TaskSession session : getTaskSessions())
		{
			session.getSupplies().forEach((itemId, supply) ->
			{
				final SupplyEntry existing = combined.get(itemId);
				if (existing == null)
				{
					combined.put(itemId,
						new SupplyEntry(supply.getQuantity(), supply.getValue(), supply.isDoseBased(),
						supply.getComponentHundredths()));
				}
				else
				{
					existing.add(supply.getQuantity(), supply.getValue(), supply.getComponentHundredths());
				}
			});
		}
		return combined;
	}

	Map<Integer, Long> getItemValues()
	{
		if (itemValues == null)
		{
			itemValues = new LinkedHashMap<>();
		}
		final Map<Integer, Long> combined = new LinkedHashMap<>(itemValues);
		for (TaskSession session : getTaskSessions())
		{
			session.getItemValues().forEach((itemId, value) ->
				combined.merge(itemId, value, Long::sum));
		}
		return combined;
	}

	void addKills(int count)
	{
		kills += count;
	}

	void addKills(String sessionId, int count)
	{
		final TaskSession session = findSession(sessionId);
		if (session != null)
		{
			session.addKills(count);
		}
		else
		{
			addKills(count);
		}
	}

	void addItem(int itemId, int quantity)
	{
		ensureLegacyItems();
		items.merge(itemId, quantity, Integer::sum);
	}

	void addItem(String sessionId, int itemId, int quantity)
	{
		final TaskSession session = findSession(sessionId);
		if (session != null)
		{
			session.addItem(itemId, quantity);
		}
		else
		{
			ensureLegacyItems();
			items.merge(itemId, quantity, Integer::sum);
		}
	}

	void addItem(String sessionId, int itemId, int quantity, long value)
	{
		final TaskSession session = findSession(sessionId);
		if (session != null)
		{
			session.addItem(itemId, quantity, value);
		}
		else
		{
			ensureLegacyItems();
			if (itemValues == null)
			{
				itemValues = new LinkedHashMap<>();
			}
			items.merge(itemId, quantity, Integer::sum);
			itemValues.merge(itemId, value, Long::sum);
		}
	}

	/** Applies one diff's cost and folds its breakdown into the running totals. */
	void addSupplyCharge(SupplyCharge charge)
	{
		ensureLegacySupplies();
		supplyCost += charge.getTotal();

		for (SupplyCharge.Row row : charge.getRows())
		{
			final SupplyEntry existing = supplies.get(row.getItemId());
			if (existing == null)
			{
				supplies.put(row.getItemId(),
					new SupplyEntry(row.getQuantity(), row.getValue(), row.isDoseBased(),
						row.getComponentHundredths()));
			}
			else
			{
				existing.add(row.getQuantity(), row.getValue(), row.getComponentHundredths());
			}
		}
	}

	void addSupplyCharge(String sessionId, SupplyCharge charge)
	{
		final TaskSession session = findSession(sessionId);
		if (session != null)
		{
			session.addSupplyCharge(charge);
		}
		else
		{
			addSupplyCharge(charge);
		}
	}

	long getSupplyCost()
	{
		return supplyCost
			+ getTaskSessions().stream().mapToLong(TaskSession::getSupplyCost).sum();
	}

	/**
	 * The task's kill count: whichever of the two counts is larger.
	 *
	 * <p>Not a sum — they measure the same kills by different means, so adding them would double
	 * every kill that both saw. The counter is authoritative and normally wins. The attributed
	 * side is taken when it leads for two reasons: records stored before {@code counterKills}
	 * existed carry no counter total at all, and a death can be credited without counter movement
	 * to match it, which is how loot for a kill the counter had already banked still lands.
	 */
	int getKills()
	{
		return Math.max(counterKills, getAttributedKills());
	}

	/** Kills tied to an observed death, and so to a session. Always {@code <=} {@link #getKills()}. */
	int getAttributedKills()
	{
		return kills + getTaskSessions().stream().mapToInt(TaskSession::getKills).sum();
	}

	/** Records assignment-counter movement, which is one kill per unit by definition. */
	void addCounterKills(int count)
	{
		counterKills += count;
	}

	TaskSession openNewSession(long now, boolean openedManually)
	{
		final TaskSession session = new TaskSession(UUID.randomUUID().toString(), now, openedManually);
		getTaskSessions().add(session);
		return session;
	}

	TaskSession resumeSession(String sessionId, long now)
	{
		return resumeSession(sessionId, now, true);
	}

	TaskSession resumeSession(String sessionId, long now, boolean openedManually)
	{
		for (TaskSession session : getTaskSessions())
		{
			if (session.getSessionId().equals(sessionId))
			{
				session.resume(now, openedManually);
				return session;
			}
		}
		return null;
	}

	TaskSession latestClosedSession()
	{
		for (int i = getTaskSessions().size() - 1; i >= 0; i--)
		{
			final TaskSession session = getTaskSessions().get(i);
			if (!session.isOpen())
			{
				return session;
			}
		}
		return null;
	}

	void closeSession(String sessionId, long now, String reason)
	{
		for (TaskSession session : getTaskSessions())
		{
			if (session.getSessionId().equals(sessionId))
			{
				session.close(now, reason);
				return;
			}
		}
	}

	void closeOpenSessions(long now, String reason)
	{
		for (TaskSession session : getTaskSessions())
		{
			if (session.isOpen())
			{
				session.close(now, reason);
			}
		}
	}

	/**
	 * Advances the named session's clock by one tick.
	 *
	 * @return whether a session by that name was found and was open. False means the caller's
	 * belief that a session is running disagrees with the record, which is worth repairing
	 * rather than absorbing: a closed session ticks nothing, and the panel's clock simply stops.
	 */
	boolean tickSession(String sessionId)
	{
		for (TaskSession session : getTaskSessions())
		{
			if (session.getSessionId().equals(sessionId))
			{
				if (!session.isOpen())
				{
					return false;
				}
				session.tick();
				return true;
			}
		}
		return false;
	}

	boolean mergeSessions(String targetId, String sourceId)
	{
		TaskSession target = null;
		TaskSession source = null;
		for (TaskSession session : getTaskSessions())
		{
			if (session.getSessionId().equals(targetId))
			{
				target = session;
			}
			else if (session.getSessionId().equals(sourceId))
			{
				source = session;
			}
		}

		if (target == null || source == null || target.isOpen() || source.isOpen())
		{
			return false;
		}

		target.mergeFrom(source);
		getTaskSessions().remove(source);
		return true;
	}

	/** Pools another assignment record into this one without changing this record's identity. */
	void mergeRecord(TaskLootRecord other)
	{
		final boolean thisWasCompleted = isCompleted();
		ensureLegacyItems();
		other.ensureLegacyItems();
		other.items.forEach((itemId, quantity) -> items.merge(itemId, quantity, Integer::sum));

		if (itemValues == null)
		{
			itemValues = new LinkedHashMap<>();
		}
		if (other.itemValues != null)
		{
			other.itemValues.forEach((itemId, value) ->
				itemValues.merge(itemId, value, Long::sum));
		}

		ensureLegacySupplies();
		other.ensureLegacySupplies();
		other.supplies.forEach((itemId, supply) ->
		{
			final SupplyEntry existing = supplies.get(itemId);
			if (existing == null)
			{
				supplies.put(itemId,
					new SupplyEntry(supply.getQuantity(), supply.getValue(), supply.isDoseBased(),
						supply.getComponentHundredths()));
			}
			else
			{
				existing.add(supply.getQuantity(), supply.getValue(), supply.getComponentHundredths());
			}
		});

		kills += other.kills;
		counterKills += other.counterKills;
		supplyCost += other.supplyCost;
		sessions += other.sessions;
		onTaskTicks += other.onTaskTicks;
		getTaskSessions().addAll(other.getTaskSessions());
		startedAt = Math.min(startedAt, other.startedAt);
		initialAmount += other.initialAmount;
		if (thisWasCompleted)
		{
			endedAt = Math.max(endedAt, other.endedAt);
		}
	}

	private TaskSession findSession(String sessionId)
	{
		if (sessionId == null)
		{
			return null;
		}
		for (TaskSession session : getTaskSessions())
		{
			if (sessionId.equals(session.getSessionId()))
			{
				return session;
			}
		}
		return null;
	}

	private void ensureLegacyItems()
	{
		if (items == null)
		{
			items = new LinkedHashMap<>();
		}
	}

	private void ensureLegacySupplies()
	{
		if (supplies == null)
		{
			supplies = new LinkedHashMap<>();
		}
	}

	int getSessions()
	{
		// The scalar is retained as a migration baseline for snapshots written before
		// sessions had identities and segments.
		return sessions + getTaskSessions().size();
	}

	int getOnTaskTicks()
	{
		return onTaskTicks
			+ getTaskSessions().stream().mapToInt(TaskSession::getOnTaskTicks).sum();
	}

	boolean isCompleted()
	{
		return endedAt > 0;
	}
}

package com.slayertaskloot;

import net.runelite.api.gameval.ItemID;

/** Which dart a toxic blowpipe is loaded with. */
